Object.assign(window.SKY_I18N.meta, {"it": {"title": "SkyTrack — Conosci la turbolenza prima di volare", "desc": "SkyTrack controlla la rotta davanti a qualsiasi volo e ti dice in parole semplici se c'è turbolenza: verde, giallo o rosso. Gratuito e open source. Prova la demo web o scarica l'app. Senza account e senza chiave API."}, "ru": {"title": "SkyTrack — Знайте о турбулентности до полёта", "desc": "SkyTrack проверяет маршрут впереди любого рейса и простыми словами говорит, есть ли турбулентность: зелёный, жёлтый или красный. Бесплатно и с открытым кодом. Попробуйте веб-демо или скачайте приложение. Без аккаунта и ключа API."}, "pt": {"title": "SkyTrack — Conheça a turbulência antes de voar", "desc": "O SkyTrack verifica a rota à frente de qualquer voo e diz-lhe em palavras simples se há turbulência: verde, amarelo ou vermelho. Gratuito e de código aberto. Experimente a demo web ou transfira a aplicação. Sem conta e sem chave API."}, "pl": {"title": "SkyTrack — Poznaj turbulencję przed lotem", "desc": "SkyTrack sprawdza trasę przed dowolnym lotem i prostymi słowami mówi, czy jest turbulencja: zielony, żółty lub czerwony. Darmowy i open source. Wypróbuj demo online lub pobierz aplikację. Bez konta i bez klucza API."}, "fa": {"title": "SkyTrack — تلاطم را پیش از پرواز بشناسید", "desc": "SkyTrack مسیر جلوی هر پروازی را بررسی می‌کند و با زبان ساده می‌گوید تلاطم هست یا نه: سبز، زرد یا قرمز. رایگان و متن‌باز. دموی وب را امتحان کنید یا برنامه را دانلود کنید. بدون حساب کاربری و بدون کلید API."}, "sw": {"title": "SkyTrack — Jua msukosuko kabla ya kusafiri", "desc": "SkyTrack hukagua njia iliyo mbele ya safari yoyote na kukuambia kwa maneno rahisi kama kuna msukosuko: kijani, njano au nyekundu. Bure na chanzo huria. Jaribu onyesho la wavuti au pakua programu. Bila akaunti na bila ufunguo wa API."}});
Object.assign(window.SKY_I18N.dicts, {
  it: {"top.dl": "persone l'hanno scaricato", "top.new": "Scopri le novità", "nav.demo": "Demo web", "nav.features": "Funzioni", "nav.download": "Download", "nav.faq": "FAQ", "nav.data": "Dati", "hero.badge": "Gratuito e open source · v0.7.8", "hero.h1a": "Conosci la turbolenza", "hero.h1b": "prima di volare.", "hero.lead": "Clicca su un volo e SkyTrack controlla la rotta davanti, alla sua quota, poi te lo dice in parole semplici: verde, giallo o rosso. Gratuito, open source, senza account e senza chiave API.", "hero.try": "Prova la demo web", "hero.console": "Installa da console", "hero.trust": "Disponibile anche per macOS e Linux", "hero.mobile": "SkyTrack è un'app per desktop. Apri questa pagina sul computer per scaricarla.", "hero.copylink": "Copia il link della pagina", "hero.cap": "Voli reali e dati in tempo reale, direttamente dall'app.", "st.freeb": "Gratuito", "st.free": "Open source, licenza MIT", "st.nokey": "Nessuna chiave", "st.nokeyd": "Senza account e senza chiave API", "st.planes": "aerei disegnati in circa 8 ms", "st.lang": "lingue dell'interfaccia", "t.eyebrow": "Turbolenza davanti", "t.h2": "Verde, giallo o rosso. In parole semplici.", "t.sub": "SkyTrack guarda la rotta davanti all'aereo, alla sua quota, usando gli avvisi ufficiali SIGMET e G-AIRMET e i recenti rapporti dei piloti.", "t.g": "Verde", "t.gp": "Niente di segnalato o previsto sulla rotta davanti.", "t.y": "Giallo", "t.yp": "È possibile turbolenza moderata. La scheda mostra più o meno a che distanza.", "t.r": "Rosso", "t.rp": "Alto rischio di turbolenza davanti, con la distanza.", "t.try": "Provalo nel browser", "t.dl": "Scarica l'app per desktop", "t.note": "La demo web usa voli simulati. L'app per desktop mostra voli reali e in diretta.", "f.eyebrow": "Funzioni", "f.h2": "Tutto ciò che serve per seguire un volo", "f.sub": "Da una rapida occhiata a chi sorvola casa tua fino alla pianificazione intorno alla turbolenza, tutto in una finestra calma e veloce.", "g.track": "Segui ogni volo", "a.tag": "Scheda del volo", "a.h": "Tutto su un volo, in una sola scheda", "a.p": "Clicca su un aereo qualsiasi. La scheda mostra chi lo opera, dove sta andando e come sta andando in questo momento.", "a.l1": "Compagnia, tipo di aereo, marche e foto, con la bandiera del paese di registrazione", "a.l2": "Rotta con una linea di volo animata, distanza residua e ora di arrivo stimata", "a.l3": "Altitudine, velocità, velocità verticale e vento contrario o in coda", "a.l4": "I voli di oggi dello stesso aereo, disegnati sulla mappa con un clic", "a.l5": "Un grafico di altitudine e velocità e un pulsante che salva un'immagine del volo da condividere", "m.live": "Voli in diretta", "m.livep": "Le posizioni si aggiornano ogni 15 secondi. Sposta la mappa e la nuova area si carica subito.", "m.filters": "Filtri a intervallo", "m.filtersp": "Intervalli di altitudine e velocità con due maniglie ciascuno, più aeroporto, compagnia e tipo di aereo.", "m.replay": "Replay", "m.replayp": "Riavvolgi l'ultima ora. Un'etichetta sopra il cursore mostra esattamente quale momento stai guardando.", "m.watch": "Lista di controllo", "m.watchp": "Segui un aereo e ricevi una notifica quando decolla o atterra, ovunque nel mondo.", "m.zone": "Zona di allerta", "m.zonep": "Disegna un cerchio sulla mappa e ricevi una notifica quando un aereo vi entra.", "m.emg": "Allerte di emergenza", "m.emgp": "Gli aerei che trasmettono 7500, 7600 o 7700 ricevono un anello rosso lampeggiante e una notifica.", "g.safe": "Meteo &amp; sicurezza", "b.tag": "Turbolenza davanti", "b.h": "Conosci la turbolenza prima che arrivi", "b.p": "SkyTrack guarda la rotta davanti all'aereo selezionato, alla sua quota, e te lo dice in parole semplici.", "b.l1": "Verde: niente di segnalato o previsto davanti", "b.l2": "Giallo: possibile turbolenza moderata", "b.l3": "Rosso: alto rischio di turbolenza", "b.l4": "Un livello della mappa disegna le aree di turbolenza ufficiali SIGMET e G-AIRMET in tutto il mondo", "b.note": "Basato su avvisi e recenti rapporti dei piloti. Verde significa che non c'è nulla di segnalato, non una garanzia.", "c.tag": "Vento &amp; carburante", "c.h": "Guarda il vento in cui vola il tuo volo", "c.p": "Attiva le frecce del vento a qualsiasi livello di volo e guarda formarsi le correnti a getto. Sulla scheda SkyTrack mostra vento contrario o in coda e una stima approssimativa di carburante e CO₂.", "c.l1": "Frecce del vento colorate per velocità, a sei livelli di volo da FL050 a FL390", "c.l2": "Carburante e CO₂ stimati per il resto del volo, con una barra per il carburante rimasto", "c.l3": "Ora di arrivo stimata in base alla velocità al suolo attuale", "d.tag": "Pannello aeroporto", "d.h": "Clicca su un aeroporto e vedi il quadro completo", "d.p": "Meteo attuale, METAR e TAF grezzi con la categoria VFR/IFR e arrivi e partenze in diretta. Clicca su un volo nell'elenco per aprirlo.", "d.l1": "Temperatura, vento, raffiche, visibilità e pressione", "d.l2": "Arrivi e partenze con stato (in avvicinamento, atterraggio), distanza e orario", "d.l3": "Città e paese, e un livello radar della pioggia sulla mappa", "g.tools": "Rendilo tuo", "o.tag": "Sopra di me", "o.h": "Guarda cosa vola proprio sopra di te", "o.p": "Scegli la tua posizione sulla mappa o scrivi un codice aeroporto. SkyTrack elenca gli aerei intorno a te e ti dice dove guardare.", "o.l1": "Direzione della bussola e altezza nel cielo, per ogni aereo", "o.l2": "Compagnia, rotta, tipo di aereo, distanza e quota", "o.l3": "Un raggio tutto tuo, da 5 km in su, disegnato sulla mappa", "p.tag": "Condividi &amp; diario", "p.h": "Conserva i tuoi voli e condividili", "p.p": "Salva un'immagine curata di qualsiasi volo con un clic e tieni il tuo diario di volo.", "p.l1": "Condividi immagine: rotta, nominativo e numeri, salvata e copiata negli appunti", "p.l2": "Diario di volo con distanza totale, giri del mondo e CO₂ stimata", "p.l3": "Esportazione CSV e «Aggiungi al diario» direttamente dalla scheda del volo", "n.search": "Ricerca in tutto il mondo", "n.searchp": "Trova un nominativo, delle marche, un tipo di aereo o un aeroporto ovunque nel mondo, non solo sullo schermo.", "n.alerts": "Allerte per ciò che ami", "n.alertsp": "Ricevi una notifica quando compare un tipo raro come l'A380, un elicottero, un aereo militare o la tua compagnia preferita.", "n.units": "Le tue unità", "n.unitsp": "Chilometri, miglia o miglia nautiche, piedi o metri, nodi, km/h o mph, °C o °F, formato 12 o 24 ore.", "n.upd": "Si aggiorna da solo", "n.updp": "Le nuove versioni si scaricano in background e si installano al riavvio. Non serve tornare su questa pagina.", "n.tray": "Resta nell'area di notifica", "n.trayp": "Chiudi la finestra e SkyTrack continua a controllare la tua lista, così le notifiche arrivano comunque.", "n.tour": "Facile da iniziare", "n.tourp": "Un breve tour al primo avvio mostra a cosa serve ogni cosa. Puoi rivederlo quando vuoi.", "n.sat": "Nuvole da satellite &amp; scie", "n.satp": "Vere immagini satellitari con le nuvole sotto gli aerei e scie che mostrano dove è stato ciascuno.", "n.stats": "Statistiche &amp; replay più lungo", "n.statsp": "Guarda cosa c'è in aria adesso: aeroporti più trafficati, compagnie e tipi più frequenti. Riavvolgi di 1, 3 o 6 ore.", "n.route": "Controllo rotta", "n.routep": "Scegli due aeroporti e vedi quale turbolenza è segnalata lungo il percorso, a tre quote di crociera.", "n.wf": "Segui un volo dal numero", "n.wfp": "Inserisci TK1 prima della partenza. Ricevi una notifica quando è in volo e quando la rotta davanti diventa mossa.", "n.seat": "Consigli per il posto", "n.seatp": "Da che parte c'è il sole e dove in cabina senti meno la turbolenza.", "n.rel": "Dati su cui contare", "n.relp": "La mappa parte dalle ultime posizioni note e dice chiaramente quando le fonti di dati gratuite sono occupate. Aggiungi la tua chiave OpenSky per averne di più.", "g.explore": "Esplora &amp; osserva", "e.tag": "Livelli della mappa", "e.h": "Livelli per ogni umore", "e.p": "Attiva i livelli con un clic: turbolenza, vento, radar della pioggia e un'ombra di giorno e notte in diretta su tutto il pianeta.", "e.l1": "Giorno e notte, aggiornati ogni minuto", "e.l2": "Stili di mappa standard, chiaro e scuro", "e.l3": "Chiudi qualsiasi sezione del menu, anche l'elenco degli aerei. SkyTrack ricorda cosa hai chiuso.", "m.spot": "Modalità plane spotter", "m.spotp": "Un registro, badge «nuovo aereo» e «nuovo tipo», dettagli extra ed esportazione CSV. Disattivata per impostazione predefinita.", "m.demo": "Modalità demo", "m.demop": "45 voli simulati, senza bisogno di internet. Il tempo scorre 30 volte più veloce.", "m.lang": "Quindici lingue", "m.langp": "Cambia l'intera interfaccia tra inglese, turco, spagnolo, tedesco, francese, arabo, cinese, giapponese, coreano, italiano, russo, portoghese, polacco, persiano e swahili.", "m.fast": "Veloce con tanti aerei", "m.fastp": "Tutti gli aerei sono disegnati su un unico canvas. Circa 3.700 aerei sull'Europa si disegnano in circa 8 ms.", "new.eyebrow": "Novità", "new.h2": "Nell'ultima versione", "new.fb": "Caricamento delle note di rilascio…", "dl.all": "Tutte le versioni", "dl.eyebrow": "Download", "dl.h2": "Scarica SkyTrack in un minuto", "dl.sub": "Scegli il modo più adatto a te. Entrambi sono gratuiti e non serve un account.", "dl.win": "Un clic, poi avvia il programma di installazione", "dl.winp": "Scarica il programma di installazione ed eseguilo. SkyTrack si apre subito dopo.", "dl.m1": "Windows 10 o successivo, 64 bit", "dl.m2": "Senza account, senza chiave API, senza pubblicità", "dl.m3": "Open source (MIT): leggi o compila il codice da solo", "dl.warn": "Windows potrebbe mostrare «Windows ha protetto il PC» perché il programma di installazione non è ancora firmato. Scegli <b>Ulteriori informazioni</b> → <b>Esegui comunque</b>.", "dl.con": "Oppure installa da console", "dl.conp": "Ti servono", "dl.and": "e", "dl.copy": "Copia", "dl.build": "Per compilare un programma di installazione da solo, esegui", "dl.live": "La modalità live funziona solo dall'app per desktop, non in un browser.", "q.eyebrow": "FAQ", "q.h2": "Domande, con risposta", "q1": "SkyTrack è davvero gratuito?", "q1a": "Sì. È gratuito e open source con licenza MIT. Niente pubblicità, niente account, niente chiave API.", "q2": "Perché Windows mi avvisa quando eseguo il programma di installazione?", "q2a": "Il programma di installazione non è ancora firmato e Windows avvisa per ogni app non firmata. Scegli «Ulteriori informazioni», poi «Esegui comunque». Il codice sorgente completo è su GitHub se vuoi controllarlo o compilarlo da solo.", "q3": "Funziona su macOS e Linux?", "q3a": "Sì. Per ogni versione vengono compilati programmi di installazione per Windows, macOS (.dmg) e Linux (.AppImage) e il pulsante di download sceglie quello giusto per il tuo computer. macOS potrebbe avvisare perché l'app non è ancora firmata: clicca con il tasto destro sull'app e scegli Apri.", "q4": "Da dove vengono i dati?", "q4a": "Dati aperti della comunità: adsb.lol e adsb.fi per le posizioni live, OpenSky come riserva, adsbdb.com per rotte e foto, Open-Meteo e aviationweather.gov per meteo, vento e turbolenza. Vedi l'elenco qui sotto.", "q5": "Vedo solo pochi aerei. Perché?", "q5a": "Le fonti gratuite hanno limiti rigidi sulle richieste e coprono solo una parte della vista ampia. Ingrandisci e compariranno più aerei. La copertura è più scarsa sugli oceani e in alcuni paesi.", "q6": "Cosa significa una linea verde di turbolenza?", "q6a": "Significa che non è segnalata né prevista turbolenza sulla rotta davanti, a quella quota. Non è una garanzia: la turbolenza in aria chiara spesso non si può prevedere.", "q7": "Quanto sono accurati i numeri di carburante e CO₂?", "q7a": "Sono stime approssimative basate sul consumo tipico in crociera per tipo di aereo. Il carico reale di carburante di un volo non è pubblico, quindi considera la barra un'illustrazione.", "q9": "Come aggiorno SkyTrack?", "q9a": "Dalla versione 0.7.0 le app per Windows e Linux si aggiornano da sole: in fondo al menu compare una barra quando una nuova versione è pronta. Su macOS la barra rimanda al download. Le versioni precedenti richiedono prima un aggiornamento manuale alla 0.7.0.", "q10": "Esiste una versione web?", "q10a": "C'è una demo web con voli e aree di turbolenza simulati, così puoi provare SkyTrack senza installare nulla. I dati live richiedono l'app per desktop, perché le fonti di dati gratuite non permettono richieste da pagine web.", "q11": "Perché vedo meno aerei in alcune regioni?", "q11a": "SkyTrack usa feed ADS-B gratuiti gestiti da volontari con i loro ricevitori. Europa e Nord America sono coperte in modo fitto, mentre in parti del Medio Oriente, dell'Africa e sugli oceani i ricevitori sono molto meno, quindi vedi meno aerei che sui tracker commerciali. Quando succede, la riga di stato lo dice. Dopo aver spostato la mappa in una nuova area, SkyTrack la riempie cerchio dopo cerchio, a partire dal centro, così i primi aerei compaiono entro un secondo o due.", "q8": "Posso aiutare o segnalare un bug?", "q8a": "Sì, volentieri. Apri una issue o una pull request su", "s.eyebrow": "Fonti dei dati", "s.h2": "Costruito su dati aperti", "s.sub": "SkyTrack non ha bisogno di alcuna chiave perché tutte queste fonti sono gratuite.", "s.1": "Posizioni live e voli di oggi", "s.2": "Vista ampia e riserva", "s.3": "Rotta, tipo, marche, foto", "s.4": "METAR, TAF, turbolenza, rapporti dei piloti", "s.5": "Meteo e vento degli aeroporti", "s.6": "Radar della pioggia", "s.7": "Foto di aeroporti, città e mappe", "ft.made": "Creato da Samet Duhan Şahin"},
  ru: {"top.dl": "человек скачали", "top.new": "Что нового", "nav.demo": "Веб-демо", "nav.features": "Возможности", "nav.download": "Скачать", "nav.faq": "Вопросы", "nav.data": "Данные", "hero.badge": "Бесплатно и с открытым кодом · v0.7.8", "hero.h1a": "Знайте о турбулентности", "hero.h1b": "до полёта.", "hero.lead": "Нажмите на любой рейс — и SkyTrack проверит маршрут впереди на его высоте и скажет простыми словами: зелёный, жёлтый или красный. Бесплатно, с открытым кодом, без аккаунта и ключа API.", "hero.try": "Попробовать веб-демо", "hero.console": "Установить из консоли", "hero.trust": "Также для macOS и Linux", "hero.mobile": "SkyTrack — приложение для компьютера. Откройте эту страницу на компьютере, чтобы скачать его.", "hero.copylink": "Скопировать ссылку на страницу", "hero.cap": "Настоящие рейсы и данные онлайн — прямо из приложения.", "st.freeb": "Бесплатно", "st.free": "Открытый код, лицензия MIT", "st.nokey": "Без ключа", "st.nokeyd": "Без аккаунта и ключа API", "st.planes": "самолётов рисуется примерно за 8 мс", "st.lang": "языков интерфейса", "t.eyebrow": "Турбулентность впереди", "t.h2": "Зелёный, жёлтый или красный. Простыми словами.", "t.sub": "SkyTrack смотрит на маршрут впереди самолёта на его высоте, используя официальные предупреждения SIGMET и G-AIRMET и недавние донесения пилотов.", "t.g": "Зелёный", "t.gp": "На маршруте впереди ничего не сообщается и не прогнозируется.", "t.y": "Жёлтый", "t.yp": "Возможна умеренная турбулентность. Карточка показывает примерно, как далеко она.", "t.r": "Красный", "t.rp": "Впереди высокий риск турбулентности, с расстоянием до неё.", "t.try": "Попробовать в браузере", "t.dl": "Скачать приложение для компьютера", "t.note": "Веб-демо использует смоделированные рейсы. Приложение для компьютера показывает настоящие рейсы онлайн.", "f.eyebrow": "Возможности", "f.h2": "Всё, что нужно, чтобы следить за рейсом", "f.sub": "От быстрого взгляда на то, кто летит над вашим домом, до планирования с учётом турбулентности — всё в одном спокойном и быстром окне.", "g.track": "Следите за каждым рейсом", "a.tag": "Карточка рейса", "a.h": "Всё о рейсе — на одной карточке", "a.p": "Нажмите на любой самолёт. Карточка покажет, кто им управляет, куда он летит и как у него дела сейчас.", "a.l1": "Авиакомпания, тип самолёта, бортовой номер и фото, с флагом страны регистрации", "a.l2": "Маршрут с анимированной линией полёта, оставшееся расстояние и расчётное время прибытия", "a.l3": "Высота, скорость, вертикальная скорость и встречный или попутный ветер", "a.l4": "Сегодняшние рейсы того же самолёта — на карте одним нажатием", "a.l5": "График высоты и скорости и кнопка, сохраняющая картинку рейса, чтобы поделиться", "m.live": "Рейсы онлайн", "m.livep": "Позиции обновляются каждые 15 секунд. Сдвиньте карту — новая область загрузится сразу.", "m.filters": "Фильтры по диапазону", "m.filtersp": "Диапазоны высоты и скорости с двумя ползунками каждый, а также аэропорт, авиакомпания и тип самолёта.", "m.replay": "Повтор", "m.replayp": "Перемотайте последний час. Метка над ползунком точно показывает, какое время вы смотрите.", "m.watch": "Список наблюдения", "m.watchp": "Следите за самолётом и получайте уведомление о взлёте или посадке в любой точке мира.", "m.zone": "Зона оповещения", "m.zonep": "Нарисуйте круг на карте и получайте уведомление, когда в него входит самолёт.", "m.emg": "Аварийные оповещения", "m.emgp": "Самолёты с кодом 7500, 7600 или 7700 получают мигающее красное кольцо и уведомление.", "g.safe": "Погода &amp; безопасность", "b.tag": "Турбулентность впереди", "b.h": "Узнайте о турбулентности до того, как она начнётся", "b.p": "SkyTrack смотрит на маршрут впереди выбранного самолёта на его высоте и сообщает простыми словами.", "b.l1": "Зелёный: впереди ничего не сообщается и не прогнозируется", "b.l2": "Жёлтый: возможна умеренная турбулентность", "b.l3": "Красный: высокий риск турбулентности", "b.l4": "Слой карты рисует официальные зоны турбулентности SIGMET и G-AIRMET по всему миру", "b.note": "На основе предупреждений и недавних донесений пилотов. Зелёный означает, что ничего не сообщается, а не гарантию.", "c.tag": "Ветер &amp; топливо", "c.h": "Смотрите, в каком ветре летит ваш рейс", "c.p": "Включите стрелки ветра на любом эшелоне и наблюдайте, как формируются струйные течения. В карточке SkyTrack показывает встречный или попутный ветер и приблизительную оценку топлива и CO₂.", "c.l1": "Стрелки ветра, окрашенные по скорости, на шести эшелонах от FL050 до FL390", "c.l2": "Оценка топлива и CO₂ на оставшуюся часть полёта, с полосой остатка топлива", "c.l3": "Расчётное время прибытия по текущей путевой скорости", "d.tag": "Панель аэропорта", "d.h": "Нажмите на аэропорт — и увидите всю картину", "d.p": "Текущая погода, сырые METAR и TAF с категорией VFR/IFR, а также прилёты и вылеты онлайн. Нажмите на рейс в списке, чтобы открыть его.", "d.l1": "Температура, ветер, порывы, видимость и давление", "d.l2": "Прилёты и вылеты со статусом (заход, посадка), расстоянием и временем", "d.l3": "Город и страна, а также слой радара осадков на карте", "g.tools": "Настройте под себя", "o.tag": "Надо мной", "o.h": "Смотрите, что летит прямо над вами", "o.p": "Выберите точку на карте или введите код аэропорта. SkyTrack перечислит самолёты вокруг вас и подскажет, куда смотреть.", "o.l1": "Направление по компасу и высота в небе для каждого самолёта", "o.l2": "Авиакомпания, маршрут, тип самолёта, расстояние и высота", "o.l3": "Собственный радиус от 5 км, нарисованный на карте", "p.tag": "Поделиться &amp; дневник", "p.h": "Храните свои рейсы и делитесь ими", "p.p": "Сохраняйте красивую картинку любого рейса одним нажатием и ведите собственный дневник полётов.", "p.l1": "Поделиться картинкой: маршрут, позывной и цифры, сохраняются и копируются в буфер обмена", "p.l2": "Дневник полётов с общим расстоянием, витками вокруг Земли и расчётным CO₂", "p.l3": "Экспорт CSV и «Добавить в дневник» прямо из карточки рейса", "n.search": "Поиск по всему миру", "n.searchp": "Находите позывной, бортовой номер, тип самолёта или аэропорт в любой точке мира, а не только на экране.", "n.alerts": "Оповещения о том, что вам нравится", "n.alertsp": "Получайте уведомление, когда появляется редкий тип, например A380, вертолёт, военный самолёт или ваша любимая авиакомпания.", "n.units": "Ваши единицы", "n.unitsp": "Километры, мили или морские мили, футы или метры, узлы, км/ч или миль/ч, °C или °F, 12- или 24-часовой формат.", "n.upd": "Обновляется сам", "n.updp": "Новые версии скачиваются в фоне и устанавливаются при перезапуске. Заходить на эту страницу снова не нужно.", "n.tray": "Работает в трее", "n.trayp": "Закройте окно — SkyTrack продолжит следить за вашим списком, и уведомления всё равно придут.", "n.tour": "Легко начать", "n.tourp": "Короткий тур при первом запуске показывает, что для чего. Его можно пройти снова в любой момент.", "n.sat": "Спутниковые облака &amp; следы", "n.satp": "Настоящие спутниковые снимки с облаками под самолётами и следы, показывающие, где побывал каждый.", "n.stats": "Статистика &amp; длинный повтор", "n.statsp": "Смотрите, что в воздухе прямо сейчас: самые загруженные аэропорты, популярные авиакомпании и типы. Перематывайте на 1, 3 или 6 часов.", "n.route": "Проверка маршрута", "n.routep": "Выберите два аэропорта и посмотрите, какая турбулентность сообщается по пути на трёх крейсерских высотах.", "n.wf": "Следите за рейсом по номеру", "n.wfp": "Введите TK1 до вылета. Вы получите уведомление, когда рейс в воздухе и когда маршрут впереди становится тряским.", "n.seat": "Советы по местам", "n.seatp": "С какой стороны солнце и где в салоне турбулентность чувствуется меньше всего.", "n.rel": "Данные, на которые можно положиться", "n.relp": "Карта начинает с последних известных позиций и чётко сообщает, когда бесплатные источники данных заняты. Добавьте свой ключ OpenSky, чтобы получать больше.", "g.explore": "Исследуйте &amp; наблюдайте", "e.tag": "Слои карты", "e.h": "Слои на любой вкус", "e.p": "Включайте слои одним нажатием: турбулентность, ветер, радар осадков и живую тень дня и ночи на всей планете.", "e.l1": "День и ночь, обновляются каждую минуту", "e.l2": "Стандартный, светлый и тёмный стили карты", "e.l3": "Сворачивайте любой раздел меню, даже список самолётов. SkyTrack запомнит, что вы свернули.", "m.spot": "Режим споттера", "m.spotp": "Журнал, значки «новый самолёт» и «новый тип», дополнительные сведения и экспорт CSV. По умолчанию выключен.", "m.demo": "Демо-режим", "m.demop": "45 смоделированных рейсов, интернет не нужен. Время идёт в 30 раз быстрее.", "m.lang": "Пятнадцать языков", "m.langp": "Переключайте весь интерфейс между английским, турецким, испанским, немецким, французским, арабским, китайским, японским, корейским, итальянским, русским, португальским, польским, персидским и суахили.", "m.fast": "Быстро даже с множеством самолётов", "m.fastp": "Все самолёты рисуются на одном холсте. Около 3700 самолётов над Европой рисуются примерно за 8 мс.", "new.eyebrow": "Что нового", "new.h2": "В последней версии", "new.fb": "Загрузка заметок о выпуске…", "dl.all": "Все выпуски", "dl.eyebrow": "Скачать", "dl.h2": "Получите SkyTrack за минуту", "dl.sub": "Выберите удобный способ. Оба бесплатны, аккаунт не нужен.", "dl.win": "Один щелчок, затем запустите установщик", "dl.winp": "Скачайте установщик и запустите его. SkyTrack откроется сразу после этого.", "dl.m1": "Windows 10 или новее, 64-разрядная", "dl.m2": "Без аккаунта, без ключа API, без рекламы", "dl.m3": "Открытый код (MIT): читайте или собирайте код сами", "dl.warn": "Windows может показать «Windows защитила ваш компьютер», потому что установщик ещё не имеет цифровой подписи. Выберите <b>Подробнее</b> → <b>Выполнить в любом случае</b>.", "dl.con": "Или установите из консоли", "dl.conp": "Вам понадобятся", "dl.and": "и", "dl.copy": "Копировать", "dl.build": "Чтобы собрать установщик самостоятельно, выполните", "dl.live": "Режим онлайн работает только в приложении для компьютера, а не в браузере.", "q.eyebrow": "Вопросы", "q.h2": "Вопросы и ответы", "q1": "SkyTrack правда бесплатный?", "q1a": "Да. Он бесплатный и с открытым кодом по лицензии MIT. Без рекламы, без аккаунта и без ключа API.", "q2": "Почему Windows предупреждает меня при запуске установщика?", "q2a": "Установщик ещё не имеет цифровой подписи, а Windows предупреждает о каждом неподписанном приложении. Выберите «Подробнее», затем «Выполнить в любом случае». Весь исходный код есть на GitHub, если хотите проверить или собрать его сами.", "q3": "Работает ли на macOS и Linux?", "q3a": "Да. Установщики для Windows, macOS (.dmg) и Linux (.AppImage) собираются с каждым выпуском, а кнопка скачивания выбирает подходящий для вашего компьютера. macOS может предупредить, потому что приложение ещё не подписано: щёлкните по приложению правой кнопкой и выберите «Открыть».", "q4": "Откуда берутся данные?", "q4a": "Открытые данные сообщества: adsb.lol и adsb.fi для позиций онлайн, OpenSky как резерв, adsbdb.com для маршрутов и фото, Open-Meteo и aviationweather.gov для погоды, ветра и турбулентности. См. список ниже.", "q5": "Я вижу только несколько самолётов. Почему?", "q5a": "У бесплатных источников строгие ограничения на число запросов, и они покрывают лишь часть широкого обзора. Приблизьте карту — появится больше самолётов. Над океанами и в некоторых странах покрытие слабее.", "q6": "Что означает зелёная линия турбулентности?", "q6a": "Это значит, что на этой высоте на маршруте впереди турбулентность не сообщается и не прогнозируется. Это не гарантия: турбулентность в ясном небе часто невозможно предсказать.", "q7": "Насколько точны цифры по топливу и CO₂?", "q7a": "Это приблизительные оценки по типичному расходу топлива в крейсерском полёте для каждого типа самолёта. Реальная заправка рейса не публикуется, поэтому воспринимайте полосу как иллюстрацию.", "q9": "Как обновить SkyTrack?", "q9a": "Начиная с версии 0.7.0 приложения для Windows и Linux обновляются сами: когда новая версия готова, внизу меню появляется панель. В macOS панель ведёт на страницу загрузки. Более старым версиям сначала нужно вручную обновиться до 0.7.0.", "q10": "Есть ли веб-версия?", "q10a": "Есть веб-демо со смоделированными рейсами и зонами турбулентности — можно попробовать SkyTrack, ничего не устанавливая. Для данных онлайн нужно приложение для компьютера, потому что бесплатные источники не принимают запросы с веб-страниц.", "q11": "Почему в некоторых регионах я вижу меньше самолётов?", "q11a": "SkyTrack использует бесплатные ADS-B-потоки от волонтёров с приёмниками. Европа и Северная Америка покрыты плотно, а в частях Ближнего Востока, Африки и над океанами приёмников гораздо меньше, поэтому вы видите там меньше самолётов, чем в коммерческих трекерах. В таком случае об этом сообщает строка состояния. После перемещения карты в новую область SkyTrack заполняет её кружок за кружком, начиная с центра, поэтому первые самолёты появляются через секунду-две.", "q8": "Могу ли я помочь или сообщить об ошибке?", "q8a": "Да, пожалуйста. Откройте issue или pull request на", "s.eyebrow": "Источники данных", "s.h2": "Построено на открытых данных", "s.sub": "SkyTrack не нужен ключ, потому что все эти источники бесплатны.", "s.1": "Позиции онлайн и рейсы сегодня", "s.2": "Широкий обзор и резерв", "s.3": "Маршрут, тип, бортовой номер, фото", "s.4": "METAR, TAF, турбулентность, донесения пилотов", "s.5": "Погода и ветер в аэропортах", "s.6": "Радар осадков", "s.7": "Фото аэропортов, города и карты", "ft.made": "Автор: Samet Duhan Şahin"},
  pt: {"top.dl": "pessoas transferiram", "top.new": "Veja as novidades", "nav.demo": "Demo web", "nav.features": "Funcionalidades", "nav.download": "Transferir", "nav.faq": "FAQ", "nav.data": "Dados", "hero.badge": "Gratuito e de código aberto · v0.7.8", "hero.h1a": "Conheça a turbulência", "hero.h1b": "antes de voar.", "hero.lead": "Clique em qualquer voo e o SkyTrack verifica a rota à frente, à sua altitude, e diz-lhe em palavras simples: verde, amarelo ou vermelho. Gratuito, de código aberto, sem conta e sem chave API.", "hero.try": "Experimentar a demo web", "hero.console": "Instalar pela consola", "hero.trust": "Também para macOS e Linux", "hero.mobile": "O SkyTrack é uma aplicação para computador. Abra esta página no seu computador para a transferir.", "hero.copylink": "Copiar ligação da página", "hero.cap": "Voos reais e dados ao vivo, diretamente da aplicação.", "st.freeb": "Gratuito", "st.free": "Código aberto, licença MIT", "st.nokey": "Sem chave", "st.nokeyd": "Sem conta e sem chave API", "st.planes": "aeronaves desenhadas em cerca de 8 ms", "st.lang": "idiomas da interface", "t.eyebrow": "Turbulência à frente", "t.h2": "Verde, amarelo ou vermelho. Em palavras simples.", "t.sub": "O SkyTrack olha para a rota à frente da aeronave, à sua altitude, usando os avisos oficiais SIGMET e G-AIRMET e relatórios recentes de pilotos.", "t.g": "Verde", "t.gp": "Nada reportado nem previsto na rota à frente.", "t.y": "Amarelo", "t.yp": "É possível turbulência moderada. O cartão mostra aproximadamente a que distância.", "t.r": "Vermelho", "t.rp": "Alto risco de turbulência à frente, com a distância até ela.", "t.try": "Experimente no seu navegador", "t.dl": "Obter a aplicação para computador", "t.note": "A demo web usa voos simulados. A aplicação para computador mostra voos reais e ao vivo.", "f.eyebrow": "Funcionalidades", "f.h2": "Tudo o que precisa para seguir um voo", "f.sub": "Desde uma vista rápida de quem sobrevoa a sua casa até ao planeamento em torno da turbulência, tudo numa janela calma e rápida.", "g.track": "Siga todos os voos", "a.tag": "Cartão do voo", "a.h": "Tudo sobre um voo, num só cartão", "a.p": "Clique em qualquer avião. O cartão mostra quem o opera, para onde vai e como está neste momento.", "a.l1": "Companhia, tipo de aeronave, matrícula e foto, com a bandeira do país de registo", "a.l2": "Rota com uma linha de voo animada, distância restante e hora de chegada estimada", "a.l3": "Altitude, velocidade, velocidade vertical e vento de frente ou de cauda", "a.l4": "Os voos de hoje da mesma aeronave, desenhados no mapa com um clique", "a.l5": "Um gráfico de altitude e velocidade e um botão que guarda uma imagem do voo para partilhar", "m.live": "Voos ao vivo", "m.livep": "As posições atualizam a cada 15 segundos. Mova o mapa e a nova área carrega de imediato.", "m.filters": "Filtros por intervalo", "m.filtersp": "Intervalos de altitude e velocidade com dois cursores cada, mais aeroporto, companhia e tipo de aeronave.", "m.replay": "Repetição", "m.replayp": "Recue a última hora. Uma etiqueta por cima do cursor mostra exatamente que momento está a ver.", "m.watch": "Lista de observação", "m.watchp": "Siga uma aeronave e receba uma notificação quando descolar ou aterrar, em qualquer parte do mundo.", "m.zone": "Zona de alerta", "m.zonep": "Desenhe um círculo no mapa e seja notificado quando uma aeronave entrar nele.", "m.emg": "Alertas de emergência", "m.emgp": "As aeronaves que emitem 7500, 7600 ou 7700 recebem um anel vermelho intermitente e uma notificação.", "g.safe": "Meteorologia &amp; segurança", "b.tag": "Turbulência à frente", "b.h": "Saiba da turbulência antes de ela acontecer", "b.p": "O SkyTrack olha para a rota à frente da aeronave selecionada, à sua altitude, e diz-lhe em palavras simples.", "b.l1": "Verde: nada reportado nem previsto à frente", "b.l2": "Amarelo: possível turbulência moderada", "b.l3": "Vermelho: alto risco de turbulência", "b.l4": "Uma camada do mapa desenha as áreas de turbulência oficiais SIGMET e G-AIRMET em todo o mundo", "b.note": "Com base em avisos e relatórios recentes de pilotos. Verde significa que nada é reportado, não é uma garantia.", "c.tag": "Vento &amp; combustível", "c.h": "Veja o vento em que o seu voo viaja", "c.p": "Ative as setas de vento em qualquer nível de voo e veja as correntes de jato a formarem-se. No cartão, o SkyTrack mostra vento de frente ou de cauda e uma estimativa aproximada de combustível e CO₂.", "c.l1": "Setas de vento coloridas por velocidade, em seis níveis de voo de FL050 a FL390", "c.l2": "Combustível e CO₂ estimados para o resto do voo, com uma barra para o combustível restante", "c.l3": "Hora de chegada estimada com base na velocidade no solo atual", "d.tag": "Painel do aeroporto", "d.h": "Clique num aeroporto e veja o quadro completo", "d.p": "Meteorologia atual, METAR e TAF em bruto com a categoria VFR/IFR, e chegadas e partidas ao vivo. Clique num voo da lista para o abrir.", "d.l1": "Temperatura, vento, rajadas, visibilidade e pressão", "d.l2": "Chegadas e partidas com estado (em aproximação, aterragem), distância e hora", "d.l3": "Cidade e país, e uma camada de radar de chuva no mapa", "g.tools": "Faça-o seu", "o.tag": "Sobre mim", "o.h": "Veja o que voa mesmo por cima de si", "o.p": "Escolha o seu local no mapa ou escreva um código de aeroporto. O SkyTrack lista as aeronaves à sua volta e diz-lhe para onde olhar.", "o.l1": "Direção da bússola e altura no céu, para cada aeronave", "o.l2": "Companhia, rota, tipo de aeronave, distância e altitude", "o.l3": "O seu próprio raio, a partir de 5 km, desenhado no mapa", "p.tag": "Partilhar &amp; diário", "p.h": "Guarde os seus voos e partilhe-os", "p.p": "Guarde uma imagem bonita de qualquer voo com um clique e mantenha o seu próprio diário de voo.", "p.l1": "Partilhar imagem: rota, indicativo e números, guardada e copiada para a área de transferência", "p.l2": "Diário de voo com distância total, voltas ao mundo e CO₂ estimado", "p.l3": "Exportação CSV e «Adicionar ao diário» diretamente a partir do cartão do voo", "n.search": "Pesquisa em todo o mundo", "n.searchp": "Encontre um indicativo, matrícula, tipo de aeronave ou aeroporto em qualquer parte do mundo, não só no ecrã.", "n.alerts": "Alertas para o que ama", "n.alertsp": "Seja notificado quando aparecer um tipo raro como o A380, um helicóptero, uma aeronave militar ou a sua companhia preferida.", "n.units": "As suas unidades", "n.unitsp": "Quilómetros, milhas ou milhas náuticas, pés ou metros, nós, km/h ou mph, °C ou °F, formato de 12 ou 24 horas.", "n.upd": "Atualiza-se sozinho", "n.updp": "As novas versões são transferidas em segundo plano e instaladas ao reiniciar. Não precisa de voltar a esta página.", "n.tray": "Funciona na área de notificação", "n.trayp": "Feche a janela e o SkyTrack continua a vigiar a sua lista, por isso as notificações continuam a chegar.", "n.tour": "Fácil de começar", "n.tourp": "Uma curta visita no primeiro arranque mostra para que serve cada coisa. Pode repeti-la quando quiser.", "n.sat": "Nuvens de satélite &amp; rastos", "n.satp": "Imagens de satélite reais com nuvens por baixo das aeronaves e rastos que mostram por onde cada uma passou.", "n.stats": "Estatísticas &amp; repetição mais longa", "n.statsp": "Veja o que está no ar agora: aeroportos mais movimentados, companhias e tipos mais comuns. Recue 1, 3 ou 6 horas.", "n.route": "Verificação de rota", "n.routep": "Escolha dois aeroportos e veja que turbulência é reportada pelo caminho, a três altitudes de cruzeiro.", "n.wf": "Siga um voo pelo número", "n.wfp": "Introduza TK1 antes da partida. Receba uma notificação quando estiver no ar e quando a rota à frente ficar agitada.", "n.seat": "Dicas de lugar", "n.seatp": "Em que lado está o sol e onde na cabina sente menos a turbulência.", "n.rel": "Dados em que pode confiar", "n.relp": "O mapa começa com as últimas posições conhecidas e diz claramente quando as fontes de dados gratuitas estão ocupadas. Adicione a sua própria chave OpenSky para obter mais.", "g.explore": "Explore &amp; observe", "e.tag": "Camadas do mapa", "e.h": "Camadas para todos os humores", "e.p": "Ative camadas com um clique: turbulência, vento, radar de chuva e uma sombra de dia e noite ao vivo de todo o planeta.", "e.l1": "Dia e noite, atualizados a cada minuto", "e.l2": "Estilos de mapa padrão, claro e escuro", "e.l3": "Recolha qualquer secção do menu, até a lista de aeronaves. O SkyTrack lembra-se do que recolheu.", "m.spot": "Modo observador de aviões", "m.spotp": "Um registo, distintivos «nova aeronave» e «novo tipo», detalhes extra e exportação CSV. Desativado por predefinição.", "m.demo": "Modo demo", "m.demop": "45 voos simulados, sem precisar de internet. O tempo corre 30 vezes mais depressa.", "m.lang": "Quinze idiomas", "m.langp": "Altere toda a interface entre inglês, turco, espanhol, alemão, francês, árabe, chinês, japonês, coreano, italiano, russo, português, polaco, persa e suaíli.", "m.fast": "Rápido com muitas aeronaves", "m.fastp": "Todas as aeronaves são desenhadas numa única tela. Cerca de 3700 aeronaves sobre a Europa desenham-se em cerca de 8 ms.", "new.eyebrow": "Novidades", "new.h2": "Na versão mais recente", "new.fb": "A carregar as notas da versão…", "dl.all": "Todas as versões", "dl.eyebrow": "Transferir", "dl.h2": "Obtenha o SkyTrack num minuto", "dl.sub": "Escolha o modo que mais lhe convém. Ambos são gratuitos e não é preciso conta.", "dl.win": "Um clique, depois execute o instalador", "dl.winp": "Transfira o instalador e execute-o. O SkyTrack abre logo a seguir.", "dl.m1": "Windows 10 ou posterior, 64 bits", "dl.m2": "Sem conta, sem chave API, sem anúncios", "dl.m3": "Código aberto (MIT): leia ou compile o código você mesmo", "dl.warn": "O Windows pode mostrar «O Windows protegeu o seu PC» porque o instalador ainda não está assinado digitalmente. Escolha <b>Mais informações</b> → <b>Executar mesmo assim</b>.", "dl.con": "Ou instale pela consola", "dl.conp": "Precisa de", "dl.and": "e", "dl.copy": "Copiar", "dl.build": "Para compilar um instalador você mesmo, execute", "dl.live": "O modo ao vivo só funciona na aplicação para computador, não num navegador.", "q.eyebrow": "FAQ", "q.h2": "Perguntas, respondidas", "q1": "O SkyTrack é mesmo gratuito?", "q1a": "Sim. É gratuito e de código aberto sob a licença MIT. Sem anúncios, sem conta e sem chave API.", "q2": "Porque é que o Windows me avisa quando executo o instalador?", "q2a": "O instalador ainda não está assinado digitalmente e o Windows avisa sobre todas as aplicações não assinadas. Escolha «Mais informações» e depois «Executar mesmo assim». O código-fonte completo está no GitHub, se quiser verificá-lo ou compilá-lo você mesmo.", "q3": "Funciona em macOS e Linux?", "q3a": "Sim. São compilados instaladores para Windows, macOS (.dmg) e Linux (.AppImage) a cada versão, e o botão de transferência escolhe o certo para o seu computador. O macOS pode avisar porque a aplicação ainda não está assinada: clique com o botão direito na aplicação e escolha Abrir.", "q4": "De onde vêm os dados?", "q4a": "Dados abertos da comunidade: adsb.lol e adsb.fi para posições ao vivo, OpenSky como reserva, adsbdb.com para rotas e fotos, Open-Meteo e aviationweather.gov para meteorologia, vento e turbulência. Veja a lista abaixo.", "q5": "Só vejo algumas aeronaves. Porquê?", "q5a": "As fontes gratuitas têm limites de pedidos rigorosos e só cobrem parte de uma vista ampla. Aproxime e aparecem mais aeronaves. A cobertura é mais fraca sobre os oceanos e em alguns países.", "q6": "O que significa uma linha verde de turbulência?", "q6a": "Significa que não há turbulência reportada nem prevista na rota à frente, a essa altitude. Não é uma garantia: a turbulência em céu limpo muitas vezes não se consegue prever.", "q7": "Quão precisos são os números de combustível e CO₂?", "q7a": "São estimativas aproximadas com base no consumo típico em cruzeiro por tipo de aeronave. A carga real de combustível de um voo não é pública, por isso trate a barra como uma ilustração.", "q9": "Como atualizo o SkyTrack?", "q9a": "A partir da versão 0.7.0 as aplicações para Windows e Linux atualizam-se sozinhas: aparece uma barra no fundo do menu quando uma nova versão está pronta. No macOS a barra leva à transferência. As versões mais antigas precisam primeiro de uma atualização manual para a 0.7.0.", "q10": "Existe uma versão web?", "q10a": "Há uma demo web com voos e áreas de turbulência simulados, para experimentar o SkyTrack sem instalar nada. Os dados ao vivo precisam da aplicação para computador, porque as fontes de dados gratuitas não permitem pedidos a partir de páginas web.", "q11": "Porque vejo menos aeronaves em algumas regiões?", "q11a": "O SkyTrack usa feeds ADS-B gratuitos mantidos por voluntários com recetores. A Europa e a América do Norte estão densamente cobertas, enquanto partes do Médio Oriente, de África e os oceanos têm muito menos recetores, por isso vê menos aeronaves aí do que nos rastreadores comerciais. Quando é esse o caso, a linha de estado di-lo. Depois de mover o mapa para uma nova área, o SkyTrack preenche-a círculo a círculo, começando pelo centro, e as primeiras aeronaves aparecem num ou dois segundos.", "q8": "Posso ajudar ou reportar um erro?", "q8a": "Sim, por favor. Abra uma issue ou um pull request em", "s.eyebrow": "Fontes de dados", "s.h2": "Construído sobre dados abertos", "s.sub": "O SkyTrack não precisa de chave porque todas estas fontes são de utilização gratuita.", "s.1": "Posições ao vivo e voos de hoje", "s.2": "Vista ampla e reserva", "s.3": "Rota, tipo, matrícula, foto", "s.4": "METAR, TAF, turbulência, relatórios de pilotos", "s.5": "Meteorologia e vento dos aeroportos", "s.6": "Radar de chuva", "s.7": "Fotos de aeroportos, cidades e mapas", "ft.made": "Criado por Samet Duhan Şahin"},
  pl: {"top.dl": "osób pobrało", "top.new": "Zobacz nowości", "nav.demo": "Demo online", "nav.features": "Funkcje", "nav.download": "Pobierz", "nav.faq": "FAQ", "nav.data": "Dane", "hero.badge": "Darmowy i open source · v0.7.8", "hero.h1a": "Poznaj turbulencję", "hero.h1b": "przed lotem.", "hero.lead": "Kliknij dowolny lot, a SkyTrack sprawdzi trasę przed nim na jego wysokości i powie Ci prostymi słowami: zielony, żółty lub czerwony. Darmowy, open source, bez konta i bez klucza API.", "hero.try": "Wypróbuj demo online", "hero.console": "Zainstaluj z konsoli", "hero.trust": "Także dla macOS i Linuksa", "hero.mobile": "SkyTrack to aplikacja na komputer. Otwórz tę stronę na komputerze, aby ją pobrać.", "hero.copylink": "Skopiuj link do strony", "hero.cap": "Prawdziwe loty i dane na żywo, prosto z aplikacji.", "st.freeb": "Za darmo", "st.free": "Open source, licencja MIT", "st.nokey": "Bez klucza", "st.nokeyd": "Bez konta i bez klucza API", "st.planes": "samolotów rysowanych w ok. 8 ms", "st.lang": "języków interfejsu", "t.eyebrow": "Turbulencja z przodu", "t.h2": "Zielony, żółty lub czerwony. Prostymi słowami.", "t.sub": "SkyTrack patrzy na trasę przed samolotem na jego wysokości, korzystając z oficjalnych ostrzeżeń SIGMET i G-AIRMET oraz niedawnych raportów pilotów.", "t.g": "Zielony", "t.gp": "Nic nie zgłoszono ani nie prognozowano na trasie przed nami.", "t.y": "Żółty", "t.yp": "Możliwa umiarkowana turbulencja. Karta pokazuje mniej więcej, jak daleko.", "t.r": "Czerwony", "t.rp": "Wysokie ryzyko turbulencji z przodu, wraz z odległością do niej.", "t.try": "Wypróbuj w przeglądarce", "t.dl": "Pobierz aplikację na komputer", "t.note": "Demo online używa symulowanych lotów. Aplikacja na komputer pokazuje prawdziwe loty na żywo.", "f.eyebrow": "Funkcje", "f.h2": "Wszystko, czego potrzeba do śledzenia lotu", "f.sub": "Od szybkiego spojrzenia na to, kto leci nad Twoim domem, po planowanie z uwzględnieniem turbulencji — wszystko w jednym spokojnym i szybkim oknie.", "g.track": "Śledź każdy lot", "a.tag": "Karta lotu", "a.h": "Wszystko o locie na jednej karcie", "a.p": "Kliknij dowolny samolot. Karta pokazuje, kto nim lata, dokąd zmierza i jak mu idzie w tej chwili.", "a.l1": "Linia lotnicza, typ samolotu, rejestracja i zdjęcie, z flagą kraju rejestracji", "a.l2": "Trasa z animowaną linią lotu, pozostały dystans i szacowana godzina przylotu", "a.l3": "Wysokość, prędkość, prędkość pionowa oraz wiatr czołowy lub z tyłu", "a.l4": "Dzisiejsze loty tego samego samolotu, narysowane na mapie jednym kliknięciem", "a.l5": "Wykres wysokości i prędkości oraz przycisk zapisujący obraz lotu do udostępnienia", "m.live": "Loty na żywo", "m.livep": "Pozycje odświeżają się co 15 sekund. Przesuń mapę, a nowy obszar załaduje się od razu.", "m.filters": "Filtry zakresów", "m.filtersp": "Zakresy wysokości i prędkości z dwoma uchwytami każdy, a także lotnisko, linia i typ samolotu.", "m.replay": "Powtórka", "m.replayp": "Przewiń ostatnią godzinę. Etykieta nad suwakiem dokładnie pokazuje, jaki czas oglądasz.", "m.watch": "Lista obserwowanych", "m.watchp": "Obserwuj samolot i dostawaj powiadomienie o starcie lub lądowaniu w dowolnym miejscu na świecie.", "m.zone": "Strefa alertu", "m.zonep": "Narysuj okrąg na mapie i dostań powiadomienie, gdy wejdzie do niego samolot.", "m.emg": "Alerty awaryjne", "m.emgp": "Samoloty nadające 7500, 7600 lub 7700 dostają migający czerwony pierścień i powiadomienie.", "g.safe": "Pogoda &amp; bezpieczeństwo", "b.tag": "Turbulencja z przodu", "b.h": "Dowiedz się o turbulencji, zanim nastąpi", "b.p": "SkyTrack patrzy na trasę przed wybranym samolotem na jego wysokości i mówi Ci o tym prostymi słowami.", "b.l1": "Zielony: nic nie zgłoszono ani nie prognozowano z przodu", "b.l2": "Żółty: możliwa umiarkowana turbulencja", "b.l3": "Czerwony: wysokie ryzyko turbulencji", "b.l4": "Warstwa mapy rysuje oficjalne obszary turbulencji SIGMET i G-AIRMET na całym świecie", "b.note": "Na podstawie ostrzeżeń i niedawnych raportów pilotów. Zielony oznacza, że nic nie zgłoszono, a nie gwarancję.", "c.tag": "Wiatr &amp; paliwo", "c.h": "Zobacz wiatr, w którym leci Twój lot", "c.p": "Włącz strzałki wiatru na dowolnym poziomie lotu i obserwuj powstawanie prądów strumieniowych. Na karcie SkyTrack pokazuje wiatr czołowy lub z tyłu oraz przybliżony szacunek paliwa i CO₂.", "c.l1": "Strzałki wiatru kolorowane według prędkości, na sześciu poziomach lotu od FL050 do FL390", "c.l2": "Szacowane paliwo i CO₂ na resztę lotu, z paskiem pozostałego paliwa", "c.l3": "Szacowana godzina przylotu na podstawie aktualnej prędkości względem ziemi", "d.tag": "Panel lotniska", "d.h": "Kliknij lotnisko i zobacz pełny obraz", "d.p": "Aktualna pogoda, surowe METAR i TAF z kategorią VFR/IFR oraz przyloty i odloty na żywo. Kliknij lot na liście, aby go otworzyć.", "d.l1": "Temperatura, wiatr, porywy, widoczność i ciśnienie", "d.l2": "Przyloty i odloty ze statusem (podejście, lądowanie), odległością i czasem", "d.l3": "Miasto i kraj oraz warstwa radaru opadów na mapie", "g.tools": "Dostosuj do siebie", "o.tag": "Nade mną", "o.h": "Zobacz, co leci tuż nad Tobą", "o.p": "Wybierz swoje miejsce na mapie lub wpisz kod lotniska. SkyTrack wypisze samoloty wokół Ciebie i powie, gdzie patrzeć.", "o.l1": "Kierunek kompasu i wysokość na niebie dla każdego samolotu", "o.l2": "Linia, trasa, typ samolotu, odległość i wysokość", "o.l3": "Własny promień, od 5 km w górę, narysowany na mapie", "p.tag": "Udostępnianie &amp; dziennik", "p.h": "Zachowaj swoje loty i dziel się nimi", "p.p": "Zapisz ładny obraz dowolnego lotu jednym kliknięciem i prowadź własny dziennik lotów.", "p.l1": "Udostępnij obraz: trasa, znak wywoławczy i liczby, zapisane i skopiowane do schowka", "p.l2": "Dziennik lotów z łącznym dystansem, okrążeniami Ziemi i szacowanym CO₂", "p.l3": "Eksport CSV i „Dodaj do dziennika” prosto z karty lotu", "n.search": "Wyszukiwanie na całym świecie", "n.searchp": "Znajdź znak wywoławczy, rejestrację, typ samolotu lub lotnisko w dowolnym miejscu na świecie, nie tylko na ekranie.", "n.alerts": "Alerty dla tego, co lubisz", "n.alertsp": "Dostań powiadomienie, gdy pojawi się rzadki typ, jak A380, helikopter, samolot wojskowy lub Twoja ulubiona linia.", "n.units": "Twoje jednostki", "n.unitsp": "Kilometry, mile lub mile morskie, stopy lub metry, węzły, km/h lub mph, °C lub °F, czas 12- lub 24-godzinny.", "n.upd": "Aktualizuje się sam", "n.updp": "Nowe wersje pobierają się w tle i instalują po ponownym uruchomieniu. Nie musisz wracać na tę stronę.", "n.tray": "Działa w zasobniku", "n.trayp": "Zamknij okno, a SkyTrack nadal pilnuje Twojej listy, więc powiadomienia wciąż przychodzą.", "n.tour": "Łatwy start", "n.tourp": "Krótkie wprowadzenie przy pierwszym uruchomieniu pokazuje, do czego służy każda rzecz. Możesz je powtórzyć w dowolnej chwili.", "n.sat": "Chmury satelitarne &amp; ślady", "n.satp": "Prawdziwe zdjęcia satelitarne z chmurami pod samolotami i ślady pokazujące, gdzie każdy z nich był.", "n.stats": "Statystyki &amp; dłuższa powtórka", "n.statsp": "Zobacz, co jest teraz w powietrzu: najbardziej ruchliwe lotniska, najpopularniejsze linie i typy. Przewiń 1, 3 lub 6 godzin.", "n.route": "Sprawdzenie trasy", "n.routep": "Wybierz dwa lotniska i zobacz, jaką turbulencję zgłoszono po drodze na trzech wysokościach przelotowych.", "n.wf": "Obserwuj lot po numerze", "n.wfp": "Wpisz TK1 przed odlotem. Dostaniesz powiadomienie, gdy będzie w powietrzu i gdy trasa przed nim zrobi się wyboista.", "n.seat": "Wskazówki dotyczące miejsca", "n.seatp": "Po której stronie jest słońce i gdzie w kabinie najmniej czuć turbulencję.", "n.rel": "Dane, na których można polegać", "n.relp": "Mapa zaczyna od ostatnich znanych pozycji i wyraźnie mówi, gdy darmowe źródła danych są zajęte. Dodaj własny klucz OpenSky, aby mieć więcej.", "g.explore": "Odkrywaj &amp; obserwuj", "e.tag": "Warstwy mapy", "e.h": "Warstwy na każdy nastrój", "e.p": "Włączaj warstwy jednym kliknięciem: turbulencja, wiatr, radar opadów i cień dnia i nocy na całej planecie na żywo.", "e.l1": "Dzień i noc, aktualizowane co minutę", "e.l2": "Standardowy, jasny i ciemny styl mapy", "e.l3": "Zwijaj dowolną sekcję menu, nawet listę samolotów. SkyTrack pamięta, co zwinąłeś.", "m.spot": "Tryb obserwatora samolotów", "m.spotp": "Dziennik, odznaki „nowy samolot” i „nowy typ”, dodatkowe szczegóły i eksport CSV. Domyślnie wyłączony.", "m.demo": "Tryb demo", "m.demop": "45 symulowanych lotów, bez potrzeby internetu. Czas płynie 30 razy szybciej.", "m.lang": "Piętnaście języków", "m.langp": "Przełączaj cały interfejs między angielskim, tureckim, hiszpańskim, niemieckim, francuskim, arabskim, chińskim, japońskim, koreańskim, włoskim, rosyjskim, portugalskim, polskim, perskim i suahili.", "m.fast": "Szybki przy wielu samolotach", "m.fastp": "Wszystkie samoloty są rysowane na jednym płótnie. Około 3700 samolotów nad Europą rysuje się w ok. 8 ms.", "new.eyebrow": "Nowości", "new.h2": "W najnowszej wersji", "new.fb": "Ładowanie informacji o wydaniu…", "dl.all": "Wszystkie wydania", "dl.eyebrow": "Pobierz", "dl.h2": "Zdobądź SkyTrack w minutę", "dl.sub": "Wybierz sposób, który Ci odpowiada. Oba są darmowe i nie wymagają konta.", "dl.win": "Jedno kliknięcie, potem uruchom instalator", "dl.winp": "Pobierz instalator i uruchom go. SkyTrack otworzy się zaraz potem.", "dl.m1": "Windows 10 lub nowszy, 64-bitowy", "dl.m2": "Bez konta, bez klucza API, bez reklam", "dl.m3": "Open source (MIT): czytaj lub buduj kod samodzielnie", "dl.warn": "Windows może pokazać „System Windows ochronił ten komputer”, bo instalator nie jest jeszcze podpisany cyfrowo. Wybierz <b>Więcej informacji</b> → <b>Uruchom mimo to</b>.", "dl.con": "Albo zainstaluj z konsoli", "dl.conp": "Potrzebujesz", "dl.and": "i", "dl.copy": "Kopiuj", "dl.build": "Aby zbudować instalator samodzielnie, uruchom", "dl.live": "Tryb na żywo działa tylko w aplikacji na komputer, nie w przeglądarce.", "q.eyebrow": "FAQ", "q.h2": "Pytania i odpowiedzi", "q1": "Czy SkyTrack naprawdę jest darmowy?", "q1a": "Tak. Jest darmowy i open source na licencji MIT. Bez reklam, bez konta i bez klucza API.", "q2": "Dlaczego Windows ostrzega mnie podczas uruchamiania instalatora?", "q2a": "Instalator nie jest jeszcze podpisany cyfrowo, a Windows ostrzega przed każdą niepodpisaną aplikacją. Wybierz „Więcej informacji”, a potem „Uruchom mimo to”. Pełny kod źródłowy jest na GitHubie, jeśli chcesz go sprawdzić lub zbudować samodzielnie.", "q3": "Czy działa na macOS i Linuksie?", "q3a": "Tak. Instalatory dla Windows, macOS (.dmg) i Linuksa (.AppImage) są budowane przy każdym wydaniu, a przycisk pobierania wybiera właściwy dla Twojego komputera. macOS może ostrzegać, bo aplikacja nie jest jeszcze podpisana: kliknij aplikację prawym przyciskiem i wybierz Otwórz.", "q4": "Skąd pochodzą dane?", "q4a": "Otwarte dane społeczności: adsb.lol i adsb.fi dla pozycji na żywo, OpenSky jako zapasowe, adsbdb.com dla tras i zdjęć, Open-Meteo i aviationweather.gov dla pogody, wiatru i turbulencji. Zobacz listę poniżej.", "q5": "Widzę tylko kilka samolotów. Dlaczego?", "q5a": "Darmowe źródła mają ścisłe limity zapytań i pokrywają tylko część szerokiego widoku. Przybliż, a pojawi się więcej samolotów. Pokrycie jest słabsze nad oceanami i w niektórych krajach.", "q6": "Co oznacza zielona linia turbulencji?", "q6a": "Oznacza, że na tej wysokości na trasie przed nami nie zgłoszono ani nie prognozowano turbulencji. To nie gwarancja: turbulencji w czystym powietrzu często nie da się przewidzieć.", "q7": "Jak dokładne są liczby paliwa i CO₂?", "q7a": "To przybliżone szacunki na podstawie typowego zużycia paliwa w przelocie dla danego typu samolotu. Rzeczywisty zapas paliwa w locie nie jest publiczny, więc traktuj pasek jako ilustrację.", "q9": "Jak zaktualizować SkyTrack?", "q9a": "Od wersji 0.7.0 aplikacje na Windows i Linuksa aktualizują się same: gdy nowa wersja jest gotowa, na dole menu pojawia się pasek. Na macOS pasek prowadzi do pobierania. Starsze wersje wymagają najpierw ręcznej aktualizacji do 0.7.0.", "q10": "Czy jest wersja internetowa?", "q10a": "Jest demo online z symulowanymi lotami i obszarami turbulencji, więc możesz wypróbować SkyTrack bez instalowania czegokolwiek. Dane na żywo wymagają aplikacji na komputer, bo darmowe źródła danych nie pozwalają na zapytania ze stron internetowych.", "q11": "Dlaczego w niektórych regionach widzę mniej samolotów?", "q11a": "SkyTrack korzysta z darmowych strumieni ADS-B prowadzonych przez wolontariuszy z odbiornikami. Europa i Ameryka Północna są gęsto pokryte, natomiast części Bliskiego Wschodu, Afryki i oceany mają znacznie mniej odbiorników, więc widzisz tam mniej samolotów niż w komercyjnych trackerach. Gdy tak jest, mówi o tym wiersz stanu. Po przesunięciu mapy w nowe miejsce SkyTrack wypełnia je okrąg po okręgu, zaczynając od środka, więc pierwsze samoloty pojawiają się w ciągu sekundy lub dwóch.", "q8": "Czy mogę pomóc lub zgłosić błąd?", "q8a": "Tak, proszę. Otwórz issue lub pull request na", "s.eyebrow": "Źródła danych", "s.h2": "Zbudowane na otwartych danych", "s.sub": "SkyTrack nie potrzebuje klucza, bo wszystkie te źródła można używać za darmo.", "s.1": "Pozycje na żywo i dzisiejsze loty", "s.2": "Szeroki widok i zapas", "s.3": "Trasa, typ, rejestracja, zdjęcie", "s.4": "METAR, TAF, turbulencja, raporty pilotów", "s.5": "Pogoda i wiatr na lotniskach", "s.6": "Radar opadów", "s.7": "Zdjęcia lotnisk, miasta i mapy", "ft.made": "Autor: Samet Duhan Şahin"},
  fa: {"top.dl": "نفر دانلود کرده‌اند", "top.new": "تازه‌ها را ببینید", "nav.demo": "دموی وب", "nav.features": "ویژگی‌ها", "nav.download": "دانلود", "nav.faq": "پرسش‌ها", "nav.data": "داده‌ها", "hero.badge": "رایگان و متن‌باز · v0.7.8", "hero.h1a": "تلاطم را بشناسید", "hero.h1b": "پیش از پرواز.", "hero.lead": "روی هر پروازی کلیک کنید تا SkyTrack مسیر جلوی آن را در ارتفاعش بررسی کند و با زبان ساده بگوید: سبز، زرد یا قرمز. رایگان، متن‌باز، بدون حساب کاربری و بدون کلید API.", "hero.try": "دموی وب را امتحان کنید", "hero.console": "نصب از کنسول", "hero.trust": "برای macOS و لینوکس هم موجود است", "hero.mobile": "SkyTrack یک برنامهٔ دسکتاپ است. برای دانلود، این صفحه را روی رایانه‌تان باز کنید.", "hero.copylink": "کپی پیوند صفحه", "hero.cap": "پروازهای واقعی و داده‌های زنده، مستقیم از برنامه.", "st.freeb": "رایگان", "st.free": "متن‌باز، مجوز MIT", "st.nokey": "بدون کلید", "st.nokeyd": "بدون حساب کاربری و کلید API", "st.planes": "هواپیما در حدود ۸ میلی‌ثانیه ترسیم می‌شود", "st.lang": "زبان رابط کاربری", "t.eyebrow": "تلاطم در جلو", "t.h2": "سبز، زرد یا قرمز. با زبان ساده.", "t.sub": "SkyTrack با استفاده از هشدارهای رسمی SIGMET و G-AIRMET و گزارش‌های اخیر خلبانان، مسیر جلوی هواپیما را در ارتفاع آن بررسی می‌کند.", "t.g": "سبز", "t.gp": "چیزی در مسیر جلو گزارش یا پیش‌بینی نشده است.", "t.y": "زرد", "t.yp": "تلاطم متوسط ممکن است. کارت تقریباً نشان می‌دهد چقدر جلوتر است.", "t.r": "قرمز", "t.rp": "خطر بالای تلاطم در جلو، همراه با فاصله تا آن.", "t.try": "در مرورگرتان امتحان کنید", "t.dl": "برنامهٔ دسکتاپ را بگیرید", "t.note": "دموی وب از پروازهای شبیه‌سازی‌شده استفاده می‌کند. برنامهٔ دسکتاپ پروازهای واقعی و زنده را نشان می‌دهد.", "f.eyebrow": "ویژگی‌ها", "f.h2": "هر آنچه برای دنبال کردن یک پرواز لازم دارید", "f.sub": "از نگاهی سریع به اینکه چه کسی بالای خانه‌تان پرواز می‌کند تا برنامه‌ریزی با توجه به تلاطم، همه در یک پنجرهٔ آرام و سریع.", "g.track": "هر پروازی را دنبال کنید", "a.tag": "کارت پرواز", "a.h": "همه‌چیز دربارهٔ یک پرواز، روی یک کارت", "a.p": "روی هر هواپیما کلیک کنید. کارت نشان می‌دهد چه کسی آن را می‌راند، به کجا می‌رود و همین حالا وضعش چطور است.", "a.l1": "ایرلاین، نوع هواپیما، شمارهٔ ثبت و عکس، همراه با پرچم کشور ثبت", "a.l2": "مسیر با خط پروازی متحرک، مسافت باقی‌مانده و زمان تخمینی ورود", "a.l3": "ارتفاع، سرعت، سرعت عمودی و باد مخالف یا موافق", "a.l4": "پروازهای امروزِ همان هواپیما، با یک کلیک روی نقشه ترسیم می‌شود", "a.l5": "نمودار ارتفاع و سرعت و دکمه‌ای که تصویری از پرواز را برای اشتراک‌گذاری ذخیره می‌کند", "m.live": "پروازهای زنده", "m.livep": "موقعیت‌ها هر ۱۵ ثانیه تازه می‌شوند. نقشه را جابه‌جا کنید تا منطقهٔ جدید بلافاصله بارگذاری شود.", "m.filters": "فیلتر بازه‌ای", "m.filtersp": "بازهٔ ارتفاع و سرعت هرکدام با دو دستگیره، به‌علاوهٔ فرودگاه، ایرلاین و نوع هواپیما.", "m.replay": "بازپخش", "m.replayp": "یک ساعت گذشته را به عقب برگردانید. برچسبی بالای لغزنده دقیقاً نشان می‌دهد کدام زمان را می‌بینید.", "m.watch": "فهرست پیگیری", "m.watchp": "یک هواپیما را دنبال کنید و هنگام برخاستن یا فرود آمدنش، در هر جای دنیا، اعلان بگیرید.", "m.zone": "منطقهٔ هشدار", "m.zonep": "روی نقشه دایره‌ای بکشید و وقتی هواپیمایی وارد آن شد، اعلان بگیرید.", "m.emg": "هشدارهای اضطراری", "m.emgp": "هواپیماهایی که کد ۷۵۰۰، ۷۶۰۰ یا ۷۷۰۰ را می‌فرستند، حلقهٔ قرمز چشمک‌زن و اعلان می‌گیرند.", "g.safe": "آب‌وهوا &amp; ایمنی", "b.tag": "تلاطم در جلو", "b.h": "پیش از وقوع تلاطم از آن باخبر شوید", "b.p": "SkyTrack مسیر جلوی هواپیمای انتخاب‌شده را در ارتفاع آن بررسی می‌کند و با زبان ساده به شما می‌گوید.", "b.l1": "سبز: چیزی در جلو گزارش یا پیش‌بینی نشده", "b.l2": "زرد: تلاطم متوسط ممکن است", "b.l3": "قرمز: خطر بالای تلاطم", "b.l4": "یک لایهٔ نقشه مناطق رسمی تلاطم SIGMET و G-AIRMET را در سراسر جهان ترسیم می‌کند", "b.note": "بر پایهٔ هشدارها و گزارش‌های اخیر خلبانان. سبز یعنی چیزی گزارش نشده، نه اینکه تضمین باشد.", "c.tag": "باد &amp; سوخت", "c.h": "بادی را که پروازتان در آن پرواز می‌کند ببینید", "c.p": "پیکان‌های باد را در هر سطح پروازی روشن کنید و شکل‌گیری جت‌استریم‌ها را ببینید. روی کارت، SkyTrack باد مخالف یا موافق و تخمینی تقریبی از سوخت و CO₂ نشان می‌دهد.", "c.l1": "پیکان‌های باد با رنگ بر اساس سرعت، در شش سطح پروازی از FL050 تا FL390", "c.l2": "سوخت و CO₂ تخمینی برای بقیهٔ پرواز، با نواری برای سوخت باقی‌مانده", "c.l3": "زمان تخمینی ورود بر پایهٔ سرعت زمینی فعلی", "d.tag": "پنل فرودگاه", "d.h": "روی یک فرودگاه کلیک کنید و تصویر کامل را ببینید", "d.p": "آب‌وهوای فعلی، METAR و TAF خام همراه با دستهٔ VFR/IFR و ورودی‌ها و خروجی‌های زنده. روی یک پرواز در فهرست کلیک کنید تا باز شود.", "d.l1": "دما، باد، وزش باد، دید و فشار", "d.l2": "ورودی‌ها و خروجی‌ها با وضعیت (نزدیک شدن، فرود)، فاصله و زمان", "d.l3": "شهر و کشور و لایهٔ رادار باران روی نقشه", "g.tools": "آن را مال خودتان کنید", "o.tag": "بالای سرم", "o.h": "ببینید درست بالای سرتان چه چیزی پرواز می‌کند", "o.p": "جای خود را روی نقشه انتخاب کنید یا کد یک فرودگاه را بنویسید. SkyTrack هواپیماهای اطراف شما را فهرست می‌کند و می‌گوید کجا نگاه کنید.", "o.l1": "جهت قطب‌نما و ارتفاع در آسمان، برای هر هواپیما", "o.l2": "ایرلاین، مسیر، نوع هواپیما، فاصله و ارتفاع", "o.l3": "شعاع دلخواه شما، از ۵ کیلومتر به بالا، روی نقشه ترسیم می‌شود", "p.tag": "اشتراک‌گذاری &amp; دفترچه", "p.h": "پروازهایتان را نگه دارید و به اشتراک بگذارید", "p.p": "با یک کلیک تصویری زیبا از هر پرواز ذخیره کنید و دفترچهٔ پرواز خودتان را داشته باشید.", "p.l1": "اشتراک‌گذاری تصویر: مسیر، شناسهٔ تماس و اعداد، ذخیره و در کلیپ‌بورد کپی می‌شود", "p.l2": "دفترچهٔ پرواز با مسافت کل، دورهای دور زمین و CO₂ تخمینی", "p.l3": "خروجی CSV و «افزودن به دفترچه» مستقیم از کارت پرواز", "n.search": "جستجوی جهانی", "n.searchp": "شناسهٔ تماس، شمارهٔ ثبت، نوع هواپیما یا فرودگاه را در هر جای دنیا پیدا کنید، نه فقط روی صفحه.", "n.alerts": "هشدار برای چیزهایی که دوست دارید", "n.alertsp": "وقتی نوعی کمیاب مثل A380، بالگرد، هواپیمای نظامی یا ایرلاین موردعلاقه‌تان ظاهر شد، اعلان بگیرید.", "n.units": "واحدهای شما", "n.unitsp": "کیلومتر، مایل یا مایل دریایی، فوت یا متر، گره، km/h یا mph، °C یا °F، ساعت ۱۲ یا ۲۴ ساعته.", "n.upd": "خودش به‌روز می‌شود", "n.updp": "نسخه‌های جدید در پس‌زمینه دانلود و هنگام راه‌اندازی مجدد نصب می‌شوند. لازم نیست دوباره به این صفحه بیایید.", "n.tray": "در سینی سیستم اجرا می‌شود", "n.trayp": "پنجره را ببندید و SkyTrack همچنان فهرست شما را زیر نظر دارد، پس اعلان‌ها همچنان می‌رسند.", "n.tour": "شروع آسان", "n.tourp": "یک راهنمای کوتاه در اولین اجرا نشان می‌دهد هر چیز چه کاری می‌کند. هر زمان بخواهید می‌توانید دوباره ببینید.", "n.sat": "ابرهای ماهواره‌ای &amp; ردّها", "n.satp": "تصاویر واقعی ماهواره‌ای با ابرها زیر هواپیماها و ردّهایی که نشان می‌دهند هر یک کجا بوده است.", "n.stats": "آمار &amp; بازپخش طولانی‌تر", "n.statsp": "ببینید همین حالا چه چیزی در هواست: شلوغ‌ترین فرودگاه‌ها، پرکاربردترین ایرلاین‌ها و نوع‌ها. ۱، ۳ یا ۶ ساعت به عقب برگردید.", "n.route": "بررسی مسیر", "n.routep": "دو فرودگاه انتخاب کنید و ببینید در سه ارتفاع کروز چه تلاطمی در مسیر گزارش شده است.", "n.wf": "پرواز را با شماره دنبال کنید", "n.wfp": "پیش از برخاستن TK1 را وارد کنید. وقتی در هوا باشد و وقتی مسیر جلوی آن ناهموار شود، اعلان می‌گیرید.", "n.seat": "نکته‌های صندلی", "n.seatp": "خورشید در کدام سمت است و در کابین کجا کمترین تلاطم را حس می‌کنید.", "n.rel": "داده‌هایی که می‌توانید به آن‌ها تکیه کنید", "n.relp": "نقشه با آخرین موقعیت‌های شناخته‌شده شروع می‌شود و وقتی منابع داده رایگان مشغول‌اند به‌روشنی می‌گوید. برای داده‌های بیشتر کلید OpenSky خودتان را اضافه کنید.", "g.explore": "کاوش &amp; مشاهده", "e.tag": "لایه‌های نقشه", "e.h": "لایه‌هایی برای هر حال‌وهوا", "e.p": "لایه‌ها را با یک کلیک روشن کنید: تلاطم، باد، رادار باران و سایهٔ زندهٔ روز و شب کل سیاره.", "e.l1": "روز و شب، هر دقیقه به‌روز می‌شود", "e.l2": "سبک‌های نقشهٔ استاندارد، روشن و تیره", "e.l3": "هر بخش منو را جمع کنید، حتی فهرست هواپیماها. SkyTrack به یاد می‌سپارد چه چیزی را جمع کرده‌اید.", "m.spot": "حالت هواپیماشناس", "m.spotp": "دفتر ثبت، نشان‌های «هواپیمای جدید» و «نوع جدید»، جزئیات بیشتر و خروجی CSV. به‌طور پیش‌فرض خاموش است.", "m.demo": "حالت نمایشی", "m.demop": "۴۵ پرواز شبیه‌سازی‌شده، بدون نیاز به اینترنت. زمان ۳۰ برابر سریع‌تر می‌گذرد.", "m.lang": "پانزده زبان", "m.langp": "کل رابط را بین انگلیسی، ترکی، اسپانیایی، آلمانی، فرانسوی، عربی، چینی، ژاپنی، کره‌ای، ایتالیایی، روسی، پرتغالی، لهستانی، فارسی و سواحیلی عوض کنید.", "m.fast": "با هواپیماهای زیاد هم سریع", "m.fastp": "همهٔ هواپیماها روی یک بوم ترسیم می‌شوند. حدود ۳۷۰۰ هواپیما بالای اروپا در حدود ۸ میلی‌ثانیه ترسیم می‌شود.", "new.eyebrow": "تازه‌ها", "new.h2": "در آخرین نسخه", "new.fb": "در حال بارگذاری یادداشت‌های نسخه…", "dl.all": "همهٔ نسخه‌ها", "dl.eyebrow": "دانلود", "dl.h2": "SkyTrack را در یک دقیقه بگیرید", "dl.sub": "راهی را که به شما می‌خورد انتخاب کنید. هر دو رایگان‌اند و حساب کاربری لازم نیست.", "dl.win": "یک کلیک، سپس نصب‌کننده را اجرا کنید", "dl.winp": "نصب‌کننده را دانلود و اجرا کنید. SkyTrack بلافاصله پس از آن باز می‌شود.", "dl.m1": "Windows 10 یا جدیدتر، ۶۴ بیتی", "dl.m2": "بدون حساب کاربری، بدون کلید API، بدون تبلیغ", "dl.m3": "متن‌باز (MIT): کد را خودتان بخوانید یا بسازید", "dl.warn": "ممکن است ویندوز پیام «Windows protected your PC» را نشان دهد، چون نصب‌کننده هنوز امضای دیجیتال ندارد. <b>More info</b> ← <b>Run anyway</b> را انتخاب کنید.", "dl.con": "یا از کنسول نصب کنید", "dl.conp": "به این‌ها نیاز دارید", "dl.and": "و", "dl.copy": "کپی", "dl.build": "برای ساختن نصب‌کننده توسط خودتان، این را اجرا کنید", "dl.live": "حالت زنده فقط از برنامهٔ دسکتاپ کار می‌کند، نه در مرورگر.", "q.eyebrow": "پرسش‌ها", "q.h2": "پرسش‌ها و پاسخ‌ها", "q1": "آیا SkyTrack واقعاً رایگان است؟", "q1a": "بله. رایگان و متن‌باز با مجوز MIT است. بدون تبلیغ، بدون حساب کاربری و بدون کلید API.", "q2": "چرا هنگام اجرای نصب‌کننده ویندوز به من هشدار می‌دهد؟", "q2a": "نصب‌کننده هنوز امضای دیجیتال ندارد و ویندوز دربارهٔ هر برنامهٔ بدون امضا هشدار می‌دهد. «More info» و سپس «Run anyway» را انتخاب کنید. اگر بخواهید خودتان بررسی یا بسازید، کد منبع کامل در GitHub است.", "q3": "آیا روی macOS و لینوکس کار می‌کند؟", "q3a": "بله. با هر نسخه نصب‌کننده‌های Windows، macOS (.dmg) و لینوکس (.AppImage) ساخته می‌شود و دکمهٔ دانلود نسخهٔ مناسب رایانه‌تان را انتخاب می‌کند. ممکن است macOS هشدار دهد چون برنامه هنوز امضا نشده است: روی برنامه راست‌کلیک کنید و Open را بزنید.", "q4": "داده‌ها از کجا می‌آیند؟", "q4a": "داده‌های باز جامعه: adsb.lol و adsb.fi برای موقعیت‌های زنده، OpenSky به‌عنوان پشتیبان، adsbdb.com برای مسیرها و عکس‌ها، Open-Meteo و aviationweather.gov برای آب‌وهوا، باد و تلاطم. فهرست را در پایین ببینید.", "q5": "فقط چند هواپیما می‌بینم. چرا؟", "q5a": "منابع رایگان محدودیت شدید درخواست دارند و فقط بخشی از نمای گسترده را پوشش می‌دهند. بزرگ‌نمایی کنید تا هواپیماهای بیشتری ظاهر شوند. پوشش روی اقیانوس‌ها و برخی کشورها ضعیف‌تر است.", "q6": "خط سبز تلاطم یعنی چه؟", "q6a": "یعنی در آن ارتفاع هیچ تلاطمی در مسیر جلو گزارش یا پیش‌بینی نشده است. این تضمین نیست: تلاطم هوای صاف اغلب قابل پیش‌بینی نیست.", "q7": "اعداد سوخت و CO₂ چقدر دقیق‌اند؟", "q7a": "تخمین‌های تقریبی بر پایهٔ مصرف سوخت معمول کروز برای هر نوع هواپیما هستند. بار واقعی سوخت یک پرواز عمومی نیست، پس نوار را یک نمونهٔ تصویری بدانید.", "q9": "چطور SkyTrack را به‌روز کنم؟", "q9a": "از نسخهٔ 0.7.0 برنامه‌های Windows و لینوکس خودشان به‌روز می‌شوند: وقتی نسخهٔ جدید آماده باشد نواری پایین منو ظاهر می‌شود. در macOS نوار به صفحهٔ دانلود می‌رود. نسخه‌های قدیمی‌تر ابتدا یک‌بار به‌روزرسانی دستی به 0.7.0 لازم دارند.", "q10": "آیا نسخهٔ وب هست؟", "q10a": "یک دموی وب با پروازها و مناطق تلاطم شبیه‌سازی‌شده هست تا بدون نصب چیزی SkyTrack را امتحان کنید. داده‌های زنده به برنامهٔ دسکتاپ نیاز دارد، چون منابع داده رایگان درخواست از صفحات وب را اجازه نمی‌دهند.", "q11": "چرا در برخی مناطق هواپیماهای کمتری می‌بینم؟", "q11a": "SkyTrack از فیدهای رایگان ADS-B استفاده می‌کند که داوطلبان با گیرنده‌هایشان اداره می‌کنند. اروپا و آمریکای شمالی پوشش متراکم دارند، اما بخش‌هایی از خاورمیانه، آفریقا و اقیانوس‌ها گیرندهٔ بسیار کمتری دارند، پس آنجا هواپیماهای کمتری نسبت به ردیاب‌های تجاری می‌بینید. در این حالت خط وضعیت این را می‌گوید. پس از جابه‌جا کردن نقشه به منطقه‌ای جدید، SkyTrack آن را دایره‌به‌دایره و از مرکز پر می‌کند، پس نخستین هواپیماها ظرف یکی دو ثانیه ظاهر می‌شوند.", "q8": "آیا می‌توانم کمک کنم یا اشکالی را گزارش دهم؟", "q8a": "بله، لطفاً. یک issue یا pull request باز کنید در", "s.eyebrow": "منابع داده", "s.h2": "ساخته‌شده بر پایهٔ داده‌های باز", "s.sub": "SkyTrack به هیچ کلیدی نیاز ندارد چون همهٔ این منابع استفادهٔ رایگان دارند.", "s.1": "موقعیت‌های زنده و پروازهای امروز", "s.2": "نمای گسترده و پشتیبان", "s.3": "مسیر، نوع، شمارهٔ ثبت، عکس", "s.4": "METAR، TAF، تلاطم، گزارش‌های خلبانان", "s.5": "آب‌وهوا و باد فرودگاه‌ها", "s.6": "رادار باران", "s.7": "عکس فرودگاه‌ها، شهرها و نقشه‌ها", "ft.made": "ساختهٔ Samet Duhan Şahin"},
  sw: {"top.dl": "watu wameipakua", "top.new": "Ona mapya", "nav.demo": "Onyesho la wavuti", "nav.features": "Vipengele", "nav.download": "Pakua", "nav.faq": "Maswali", "nav.data": "Data", "hero.badge": "Bure na chanzo huria · v0.7.8", "hero.h1a": "Jua msukosuko", "hero.h1b": "kabla ya kusafiri.", "hero.lead": "Bofya safari yoyote na SkyTrack hukagua njia iliyo mbele, kwenye mwinuko wake, kisha inakuambia kwa maneno rahisi: kijani, njano au nyekundu. Bure, chanzo huria, bila akaunti na bila ufunguo wa API.", "hero.try": "Jaribu onyesho la wavuti", "hero.console": "Sakinisha kupitia console", "hero.trust": "Pia kwa macOS na Linux", "hero.mobile": "SkyTrack ni programu ya kompyuta. Fungua ukurasa huu kwenye kompyuta yako ili kuipakua.", "hero.copylink": "Nakili kiungo cha ukurasa", "hero.cap": "Safari halisi na data ya moja kwa moja, moja kwa moja kutoka kwenye programu.", "st.freeb": "Bure", "st.free": "Chanzo huria, leseni ya MIT", "st.nokey": "Bila ufunguo", "st.nokeyd": "Bila akaunti, bila ufunguo wa API", "st.planes": "ndege huchorwa kwa takriban ms 8", "st.lang": "lugha za kiolesura", "t.eyebrow": "Msukosuko mbele", "t.h2": "Kijani, njano au nyekundu. Kwa maneno rahisi.", "t.sub": "SkyTrack hutazama njia iliyo mbele ya ndege, kwenye mwinuko wake, kwa kutumia tahadhari rasmi za SIGMET na G-AIRMET na ripoti za hivi karibuni za marubani.", "t.g": "Kijani", "t.gp": "Hakuna kilichoripotiwa wala kutabiriwa kwenye njia iliyo mbele.", "t.y": "Njano", "t.yp": "Msukosuko wa wastani unawezekana. Kadi inaonyesha takriban umbali ulioko mbele.", "t.r": "Nyekundu", "t.rp": "Hatari kubwa ya msukosuko mbele, pamoja na umbali wake.", "t.try": "Jaribu kwenye kivinjari chako", "t.dl": "Pata programu ya kompyuta", "t.note": "Onyesho la wavuti hutumia safari za kuigwa. Programu ya kompyuta huonyesha safari halisi za moja kwa moja.", "f.eyebrow": "Vipengele", "f.h2": "Kila kitu unachohitaji kufuatilia safari", "f.sub": "Kuanzia mtazamo wa haraka wa nani anaruka juu ya nyumba yako hadi kupanga kwa kuzingatia msukosuko, vyote katika dirisha moja tulivu na la haraka.", "g.track": "Fuatilia kila safari", "a.tag": "Kadi ya safari", "a.h": "Kila kitu kuhusu safari, kwenye kadi moja", "a.p": "Bofya ndege yoyote. Kadi inaonyesha nani anaiendesha, inakwenda wapi na hali yake kwa sasa.", "a.l1": "Shirika, aina ya ndege, usajili na picha, pamoja na bendera ya nchi iliyosajiliwa", "a.l2": "Njia yenye mstari wa safari unaosogea, umbali uliobaki na muda wa kuwasili unaokadiriwa", "a.l3": "Mwinuko, kasi, kasi wima, na upepo wa mbele au wa nyuma", "a.l4": "Safari za leo za ndege ile ile, zinachorwa kwenye ramani kwa kubofya mara moja", "a.l5": "Chati ya mwinuko na kasi, na kitufe kinachohifadhi picha ya safari ili kushiriki", "m.live": "Safari za moja kwa moja", "m.livep": "Nafasi husasishwa kila sekunde 15. Sogeza ramani na eneo jipya hupakia mara moja.", "m.filters": "Vichujio vya kiwango", "m.filtersp": "Viwango vya mwinuko na kasi vyenye vishikio viwili kila kimoja, pamoja na uwanja wa ndege, shirika na aina ya ndege.", "m.replay": "Cheza upya", "m.replayp": "Rudisha nyuma saa ya mwisho. Lebo juu ya kitelezi inaonyesha hasa muda unaoutazama.", "m.watch": "Orodha ya kufuatilia", "m.watchp": "Fuatilia ndege na upate arifa inapoondoka au kutua, popote duniani.", "m.zone": "Eneo la tahadhari", "m.zonep": "Chora duara kwenye ramani na upate arifa ndege inapoingia ndani yake.", "m.emg": "Tahadhari za dharura", "m.emgp": "Ndege zinazotuma 7500, 7600 au 7700 hupata pete nyekundu inayopepesa na arifa.", "g.safe": "Hali ya hewa &amp; usalama", "b.tag": "Msukosuko mbele", "b.h": "Jua kuhusu msukosuko kabla haujatokea", "b.p": "SkyTrack hutazama njia iliyo mbele ya ndege uliyoichagua, kwenye mwinuko wake, na kukuambia kwa maneno rahisi.", "b.l1": "Kijani: hakuna kilichoripotiwa wala kutabiriwa mbele", "b.l2": "Njano: msukosuko wa wastani unawezekana", "b.l3": "Nyekundu: hatari kubwa ya msukosuko", "b.l4": "Safu ya ramani huchora maeneo rasmi ya msukosuko ya SIGMET na G-AIRMET duniani kote", "b.note": "Kulingana na tahadhari na ripoti za hivi karibuni za marubani. Kijani humaanisha hakuna kilichoripotiwa, si dhamana.", "c.tag": "Upepo &amp; mafuta", "c.h": "Ona upepo ambao safari yako inaruka ndani yake", "c.p": "Washa mishale ya upepo katika kiwango chochote cha safari na uone mikondo ya jeti ikitengenezwa. Kwenye kadi, SkyTrack inaonyesha upepo wa mbele au wa nyuma na makadirio ya takriban ya mafuta na CO₂.", "c.l1": "Mishale ya upepo yenye rangi kulingana na kasi, katika viwango sita vya safari kutoka FL050 hadi FL390", "c.l2": "Makadirio ya mafuta na CO₂ kwa sehemu iliyobaki ya safari, na upau wa mafuta yaliyobaki", "c.l3": "Muda wa kuwasili unaokadiriwa kulingana na kasi ya sasa juu ya ardhi", "d.tag": "Paneli ya uwanja wa ndege", "d.h": "Bofya uwanja wa ndege, upate picha nzima", "d.p": "Hali ya hewa ya sasa, METAR na TAF ghafi pamoja na kategoria ya VFR/IFR, na wanaowasili na kuondoka moja kwa moja. Bofya safari kwenye orodha ili kuifungua.", "d.l1": "Joto, upepo, pepo za ghafla, mwonekano na shinikizo", "d.l2": "Wanaowasili na kuondoka wakiwa na hali (wanakaribia, wanatua), umbali na muda", "d.l3": "Jiji na nchi, na safu ya rada ya mvua kwenye ramani", "g.tools": "Ifanye yako", "o.tag": "Juu yangu", "o.h": "Ona kinachoruka juu yako moja kwa moja", "o.p": "Chagua mahali pako kwenye ramani au andika msimbo wa uwanja wa ndege. SkyTrack inaorodhesha ndege zinazokuzunguka na inakuambia mahali pa kutazama.", "o.l1": "Mwelekeo wa dira na urefu angani, kwa kila ndege", "o.l2": "Shirika, njia, aina ya ndege, umbali na mwinuko", "o.l3": "Kipenyo chako mwenyewe, kuanzia km 5 kwenda juu, kinachorwa kwenye ramani", "p.tag": "Shiriki &amp; shajara", "p.h": "Hifadhi safari zako na uzishiriki", "p.p": "Hifadhi picha nzuri ya safari yoyote kwa kubofya mara moja, na uweke shajara yako ya safari.", "p.l1": "Shiriki picha: njia, jina la mawasiliano na namba, vinahifadhiwa na kunakiliwa kwenye ubao wa kunakili", "p.l2": "Shajara ya safari yenye umbali wote, mizunguko ya Dunia na CO₂ inayokadiriwa", "p.l3": "Uhamishaji wa CSV, na «Ongeza kwenye shajara» moja kwa moja kutoka kwenye kadi ya safari", "n.search": "Utafutaji wa dunia nzima", "n.searchp": "Pata jina la mawasiliano, usajili, aina ya ndege au uwanja wa ndege popote duniani, si tu kwenye skrini.", "n.alerts": "Tahadhari kwa unachokipenda", "n.alertsp": "Pata arifa aina adimu kama A380, helikopta, ndege ya kijeshi au shirika unalolipenda inapoonekana.", "n.units": "Vipimo vyako", "n.unitsp": "Kilomita, maili au maili za baharini, futi au mita, fundo, km/h au mph, °C au °F, muda wa saa 12 au 24.", "n.upd": "Hujisasisha yenyewe", "n.updp": "Matoleo mapya hupakuliwa chinichini na kusakinishwa unapoanzisha upya. Huhitaji kutembelea ukurasa huu tena.", "n.tray": "Hufanya kazi kwenye trei", "n.trayp": "Funga dirisha na SkyTrack inaendelea kuangalia orodha yako, kwa hivyo arifa bado zinafika.", "n.tour": "Rahisi kuanza", "n.tourp": "Ziara fupi wakati wa kuanza mara ya kwanza inaonyesha kila kitu kinafanya nini. Unaweza kuirudia wakati wowote.", "n.sat": "Mawingu ya setilaiti &amp; michirizi", "n.satp": "Picha halisi za setilaiti zenye mawingu chini ya ndege, na michirizi inayoonyesha kila moja ilikuwa wapi.", "n.stats": "Takwimu &amp; kucheza upya kwa muda mrefu", "n.statsp": "Ona kilichoko angani sasa hivi: viwanja vya ndege vyenye shughuli nyingi, mashirika na aina zinazoongoza. Rudisha nyuma saa 1, 3 au 6.", "n.route": "Ukaguzi wa njia", "n.routep": "Chagua viwanja viwili vya ndege uone msukosuko ulioripotiwa njiani, katika miinuko mitatu ya safari.", "n.wf": "Fuatilia safari kwa namba", "n.wfp": "Weka TK1 kabla ya kuondoka. Pata arifa inapokuwa angani, na njia iliyo mbele inapokuwa na misukosuko.", "n.seat": "Vidokezo vya kiti", "n.seatp": "Jua liko upande gani, na wapi kwenye kabini unahisi msukosuko kidogo zaidi.", "n.rel": "Data unayoweza kuitegemea", "n.relp": "Ramani huanza na nafasi za mwisho zinazojulikana na husema wazi vyanzo vya data vya bure vinapokuwa na shughuli nyingi. Ongeza ufunguo wako wa OpenSky kupata zaidi.", "g.explore": "Chunguza &amp; tazama", "e.tag": "Safu za ramani", "e.h": "Safu kwa kila hali", "e.p": "Washa safu kwa kubofya mara moja: msukosuko, upepo, rada ya mvua, na kivuli hai cha mchana na usiku cha sayari nzima.", "e.l1": "Mchana na usiku, vinasasishwa kila dakika", "e.l2": "Mitindo ya ramani ya kawaida, nyepesi na nyeusi", "e.l3": "Kunja sehemu yoyote ya menyu, hata orodha ya ndege. SkyTrack inakumbuka ulichokikunja.", "m.spot": "Hali ya mtazamaji wa ndege", "m.spotp": "Daftari, beji za «ndege mpya» na «aina mpya», maelezo ya ziada na uhamishaji wa CSV. Imezimwa kwa chaguo-msingi.", "m.demo": "Hali ya onyesho", "m.demop": "Safari 45 za kuigwa, bila kuhitaji intaneti. Muda unakwenda kwa kasi mara 30.", "m.lang": "Lugha kumi na tano", "m.langp": "Badilisha kiolesura chote kati ya Kiingereza, Kituruki, Kihispania, Kijerumani, Kifaransa, Kiarabu, Kichina, Kijapani, Kikorea, Kiitaliano, Kirusi, Kireno, Kipolandi, Kiajemi na Kiswahili.", "m.fast": "Haraka hata na ndege nyingi", "m.fastp": "Ndege zote huchorwa kwenye turubai moja. Takriban ndege 3,700 juu ya Ulaya huchorwa kwa takriban ms 8.", "new.eyebrow": "Mapya", "new.h2": "Kwenye toleo la hivi karibuni", "new.fb": "Inapakia maelezo ya toleo…", "dl.all": "Matoleo yote", "dl.eyebrow": "Pakua", "dl.h2": "Pata SkyTrack kwa dakika moja", "dl.sub": "Chagua njia inayokufaa. Zote ni bure, na akaunti haihitajiki.", "dl.win": "Bofya mara moja, kisha endesha kisakinishi", "dl.winp": "Pakua kisakinishi na ukiendeshe. SkyTrack hufunguka mara baada ya hapo.", "dl.m1": "Windows 10 au mpya zaidi, biti 64", "dl.m2": "Bila akaunti, bila ufunguo wa API, bila matangazo", "dl.m3": "Chanzo huria (MIT): soma au jenga msimbo mwenyewe", "dl.warn": "Windows inaweza kuonyesha «Windows protected your PC» kwa sababu kisakinishi bado hakijasainiwa kidijitali. Chagua <b>More info</b> → <b>Run anyway</b>.", "dl.con": "Au sakinisha kupitia console", "dl.conp": "Unahitaji", "dl.and": "na", "dl.copy": "Nakili", "dl.build": "Kujenga kisakinishi mwenyewe, endesha", "dl.live": "Hali ya moja kwa moja hufanya kazi tu kutoka kwenye programu ya kompyuta, si kwenye kivinjari.", "q.eyebrow": "Maswali", "q.h2": "Maswali, yamejibiwa", "q1": "Je, SkyTrack kweli ni bure?", "q1a": "Ndiyo. Ni bure na chanzo huria chini ya leseni ya MIT. Hakuna matangazo, hakuna akaunti na hakuna ufunguo wa API.", "q2": "Kwa nini Windows hunionya ninapoendesha kisakinishi?", "q2a": "Kisakinishi bado hakijasainiwa kidijitali, na Windows huonya kuhusu kila programu isiyosainiwa. Chagua «More info», kisha «Run anyway». Msimbo wote wa chanzo uko GitHub ukitaka kuukagua au kuujenga mwenyewe.", "q3": "Je, inafanya kazi kwenye macOS na Linux?", "q3a": "Ndiyo. Visakinishi vya Windows, macOS (.dmg) na Linux (.AppImage) hujengwa kwa kila toleo, na kitufe cha kupakua huchagua kinachofaa kompyuta yako. macOS inaweza kuonya kwa sababu programu bado haijasainiwa: bofya kulia programu na uchague Open.", "q4": "Data inatoka wapi?", "q4a": "Data huria ya jamii: adsb.lol na adsb.fi kwa nafasi za moja kwa moja, OpenSky kama akiba, adsbdb.com kwa njia na picha, Open-Meteo na aviationweather.gov kwa hali ya hewa, upepo na msukosuko. Tazama orodha hapa chini.", "q5": "Naona ndege chache tu. Kwa nini?", "q5a": "Vyanzo vya bure vina vikomo vikali vya maombi na hufunika sehemu tu ya mwonekano mpana. Kuza na ndege zaidi zitaonekana. Mtandao ni hafifu juu ya bahari na baadhi ya nchi.", "q6": "Mstari wa kijani wa msukosuko unamaanisha nini?", "q6a": "Inamaanisha hakuna msukosuko ulioripotiwa wala kutabiriwa kwenye njia iliyo mbele, katika mwinuko huo. Si dhamana: msukosuko wa hewa safi mara nyingi hauwezi kutabiriwa.", "q7": "Namba za mafuta na CO₂ ni sahihi kiasi gani?", "q7a": "Ni makadirio ya takriban kutokana na matumizi ya kawaida ya mafuta wakati wa safari kwa kila aina ya ndege. Kiasi halisi cha mafuta cha safari si cha umma, kwa hivyo chukulia upau kama kielelezo.", "q9": "Nasasishaje SkyTrack?", "q9a": "Kuanzia toleo la 0.7.0 programu za Windows na Linux hujisasisha zenyewe: upau huonekana chini ya menyu toleo jipya linapokuwa tayari. Kwenye macOS upau unaelekeza kwenye upakuaji. Matoleo ya zamani yanahitaji sasisho moja la mkono hadi 0.7.0 kwanza.", "q10": "Je, kuna toleo la wavuti?", "q10a": "Kuna onyesho la wavuti lenye safari na maeneo ya msukosuko ya kuigwa, ili uweze kujaribu SkyTrack bila kusakinisha chochote. Data ya moja kwa moja inahitaji programu ya kompyuta, kwa sababu vyanzo vya bure vya data haviruhusu maombi kutoka kwenye kurasa za wavuti.", "q11": "Kwa nini naona ndege chache katika baadhi ya maeneo?", "q11a": "SkyTrack hutumia vyanzo vya bure vya ADS-B vinavyoendeshwa na wajitolea wenye vipokezi. Ulaya na Amerika Kaskazini zimefunikwa kwa wingi, wakati sehemu za Mashariki ya Kati, Afrika na bahari zina vipokezi vichache zaidi, kwa hivyo unaona ndege chache huko kuliko kwenye vifuatiliaji vya kibiashara. Hali ikiwa hivyo, mstari wa hali husema hivyo. Baada ya kusogeza ramani hadi eneo jipya, SkyTrack huijaza duara kwa duara, kuanzia katikati, kwa hivyo ndege za kwanza huonekana ndani ya sekunde moja au mbili.", "q8": "Naweza kusaidia au kuripoti hitilafu?", "q8a": "Ndiyo, tafadhali. Fungua issue au pull request kwenye", "s.eyebrow": "Vyanzo vya data", "s.h2": "Imejengwa juu ya data huria", "s.sub": "SkyTrack haihitaji ufunguo kwa sababu vyanzo hivi vyote ni vya bure kutumia.", "s.1": "Nafasi za moja kwa moja na safari za leo", "s.2": "Mwonekano mpana na akiba", "s.3": "Njia, aina, usajili, picha", "s.4": "METAR, TAF, msukosuko, ripoti za marubani", "s.5": "Hali ya hewa na upepo wa viwanja vya ndege", "s.6": "Rada ya mvua", "s.7": "Picha za viwanja vya ndege, miji na ramani", "ft.made": "Imetengenezwa na Samet Duhan Şahin"}
});
